pub fn format_real(d : Double) -> String {
  if d.is_nan() {
    return "NULL"
  }
  if d.is_inf() {
    return if d > 0.0 { "Inf" } else { "-Inf" }
  }
  if d == 0.0 {
    return "0.0"
  }
  let neg = d < 0.0
  let s = "\{d.abs()}"
  // split mantissa / exponent
  let (mant, exp10) = match s.find("e") {
    Some(i) => {
      let es = s[i + 1:].to_owned()
      let ev = @string.parse_int(if es.has_prefix("+") { es[1:] } else { es[:] }) catch {
        _ => 0
      }
      (s[:i].to_owned(), ev)
    }
    None => (s, 0)
  }
  let (ip, fp) = match mant.find(".") {
    Some(i) => (mant[:i].to_owned(), mant[i + 1:].to_owned())
    None => (mant, "")
  }
  let all = ip + fp
  let mut z = 0
  while z < all.length() && all[z] == '0' {
    z += 1
  }
  let mut digits = all[z:].to_owned()
  let mut e = ip.length() - 1 - z + exp10
  // strip trailing zeros
  let mut end = digits.length()
  while end > 1 && digits[end - 1] == '0' {
    end -= 1
  }
  digits = digits[:end].to_owned()
  if digits.length() == 0 {
    return "0.0"
  }
  let sb = StringBuilder()
  if neg {
    sb.write_char('-')
  }
  if e > -5 && e < 16 {
    if e >= 0 {
      if digits.length() <= e + 1 {
        sb.write_string(digits)
        for _ in 0..<(e + 1 - digits.length()) {
          sb.write_char('0')
        }
        sb.write_string(".0")
      } else {
        sb.write_view(digits[:e + 1])
        sb.write_char('.')
        sb.write_view(digits[e + 1:])
      }
    } else {
      sb.write_string("0.")
      for _ in 0..<(-e - 1) {
        sb.write_char('0')
      }
      sb.write_string(digits)
    }
  } else {
    sb.write_view(digits[:1])
    sb.write_char('.')
    if digits.length() > 1 {
      sb.write_view(digits[1:])
    } else {
      sb.write_char('0')
    }
    sb.write_char('e')
    if e < 0 {
      sb.write_char('-')
      e = -e
    } else {
      sb.write_char('+')
    }
    if e < 10 {
      sb.write_char('0')
    }
    sb.write_string(e.to_string())
  }
  sb.to_string()
}

