fn check_function(name : String, n : Int, star : Bool) -> Unit raise SqlError {
  let arity_ok = match name {
    "TYPEOF" => n == 1 && !star
    _ => raise sql_err("no such function: \{name}")
  }
  if !arity_ok {
    raise sql_err("wrong number of arguments to function \{name.to_lower()}()")
  }
