///|
/// Stable merge sort.
fn[T] stable_sort(arr : Array[T], cmp : (T, T) -> Int) -> Unit {
  let n = arr.length()
  if n < 2 {
    return
  }
  let tmp = arr.copy()
  let mut width = 1
  while width < n {
    let mut lo = 0
    while lo < n {
      let mid = if lo + width < n { lo + width } else { n }
      let hi = if lo + 2 * width < n { lo + 2 * width } else { n }
      let mut i = lo
      let mut j = mid
      let mut k = lo
      while i < mid && j < hi {
        if cmp(arr[j], arr[i]) < 0 {
          tmp[k] = arr[j]
          j += 1
        } else {
          tmp[k] = arr[i]
          i += 1
        }
        k += 1
      }
      while i < mid {
        tmp[k] = arr[i]
        i += 1
        k += 1
      }
      while j < hi {
        tmp[k] = arr[j]
        j += 1
        k += 1
      }
      lo = hi
    }
    for x in 0..<n {
      arr[x] = tmp[x]
    }
    width *= 2
  }
}

///|
/// Run a whole script and return the output text.
pub fn run_script(db : Database, script : String) -> String {
  let sb = StringBuilder()
  for stmt in split_statements(script) {
    let rows = db.execute(stmt) catch {
      SqlError(msg) => {
        sb.write_string("Error: ")
        sb.write_string(msg)
        sb.write_char('\n')
        continue
      }
    }
    for r in rows {
      for i, v in r {
        if i > 0 {
          sb.write_char('|')
        }
        sb.write_string(v.display())
      }
      sb.write_char('\n')
    }
  }
  sb.to_string()
}
