///|
priv struct Source {
  name : String // alias or table name
  table : Table
  offset : Int // slot of the first column; rowid at offset + ncols
}

///|
priv struct Scope {
  sources : Array[Source]
}

///|
fn is_rowid_name(n : String) -> Bool {
  let l = n.to_lower()
  l == "rowid" || l == "oid" || l == "_rowid_"
}

///|
fn Scope::resolve(
  self : Scope,
  tbl : String?,
  name : String,
  dq : Bool,
) -> Expr raise SqlError {
  match tbl {
    Some(t) => {
      for s in self.sources {
        if same_name(s.name, t) {
          match s.table.col_index(name) {
            Some(i) => return Slot(s.offset + i, s.table.cols[i].affinity)
            None =>
              if is_rowid_name(name) {
                return Slot(s.offset + s.table.cols.length(), AffInteger)
              }
          }
          raise sql_err("no such column: \{t}.\{name}")
        }
      }
      raise sql_err("no such column: \{t}.\{name}")
    }
    None => {
      let mut found : Expr? = None
      for s in self.sources {
        match s.table.col_index(name) {
          Some(i) => {
            if found is Some(_) {
              raise sql_err("ambiguous column name: \{name}")
            }
            found = Some(Slot(s.offset + i, s.table.cols[i].affinity))
          }
          None => ()
        }
      }
      match found {
        Some(e) => e
        None => {
          if is_rowid_name(name) && self.sources.length() == 1 {
            let s = self.sources[0]
            return Slot(s.offset + s.table.cols.length(), AffInteger)
          }
          if dq {
            Lit(Text(name))
          } else {
            raise sql_err("no such column: \{name}")
          }
        }
      }
    }
  }
}

///|
fn Scope::bind(self : Scope, e : Expr) -> Expr raise SqlError {
  match e {
    Lit(_) | BigIntLit | Slot(_, _) => e
    Column(tbl~, name~, dq~) => self.resolve(tbl, name, dq)
    Unary(op, x) => Unary(op, self.bind(x))
    Binary(op, l, r) => Binary(op, self.bind(l), self.bind(r))
    IsNull(x, n) => IsNull(self.bind(x), n)
    Collate(x, c) => Collate(self.bind(x), c)
    Func(name~, args~, star~, distinct~) => {
      check_function(name, args.length(), star)
      let bargs : Array[Expr] = []
      for a in args {
        bargs.push(self.bind(a))
      }
      Func(name~, args=bargs, star~, distinct~)
    }
  }
}

