///|
/// Execute one statement; returns the result rows.
pub fn Database::execute(
  self : Database,
  sql : String,
) -> Array[Array[Value]] raise SqlError {
  let st = parse_statement(sql)
  match st {
    SelectStmt(sel) => self.run_select(sel)
    CreateTable(name~, if_not_exists~, cols~, constraints~, sql~) => {
      if self.tables.contains(key_of(name)) {
        if if_not_exists {
          return []
        }
        raise sql_err("table \{name} already exists")
      }
      for i, c in cols {
        for j in 0..<i {
          if same_name(cols[j].name, c.name) {
            raise sql_err("duplicate column name: \{c.name}")
          }
        }
      }
      self.tables[key_of(name)] = {
        name,
        cols,
        constraints,
        rows: [],
        max_rowid: 0L,
        sql,
        rowid_alias: find_rowid_alias(cols, constraints),
      }
      []
    }
    DropTable(name~, if_exists~) => {
      if !self.tables.contains(key_of(name)) {
        if if_exists {
          return []
        }
        raise sql_err("no such table: \{name}")
      }
      self.tables.remove(key_of(name))
      []
    }
    Insert(table~, cols~, src~, or_=_) => {
      self.run_insert(table, cols, src)
      []
    }
  }
}

