///|
fn hi_part(x : Double) -> Double {
  (x.reinterpret_as_uint64() & 0xfffffffffc000000UL).reinterpret_as_double()
}

///|
/// Dekker double-double multiply of (x0, x1) by (y, yy).
fn dekker_mul2(x : FixedArray[Double], y : Double, yy : Double) -> Unit {
  let hx = hi_part(x[0])
  let tx = x[0] - hx
  let hy = hi_part(y)
  let ty = y - hy
  let p = hx * hy
  let q1 = hx * ty
  let q2 = tx * hy
  let q = q1 + q2
  let c = p + q
  let t1 = p - c
  let t2 = t1 + q
  let t3 = tx * ty
  let mut cc = t2 + t3
  let u1 = x[0] * yy
  let u2 = x[1] * y
  cc = u1 + u2 + cc
  x[0] = c + cc
  let d = c - x[0]
  x[1] = d + cc
}

