///|
pub(all) enum BinOp {
  Add
  Sub
  Mul
  Div
  Mod
  Concat
  Eq
  Ne
  Lt
  Le
  Gt
  Ge
  And
  Or
  BitAnd
  BitOr
  Shl
  Shr
  Is
  IsNot
} derive(Eq, Debug)

///|
pub(all) enum UnOp {
  Neg
  Pos
  Not
  BitNot
} derive(Eq, Debug)

///|
pub(all) enum Expr {
  Lit(Value)
  /// Integer literal 9223372036854775808 (becomes MIN when negated).
  BigIntLit
  /// Unresolved column reference. `dq` marks a lone double-quoted name.
  Column(tbl~ : String?, name~ : String, dq~ : Bool)
  /// Resolved column: slot in the flat row, with its affinity.
  Slot(Int, Affinity, Coll)
  Unary(UnOp, Expr)
  Binary(BinOp, Expr, Expr)
  /// Bound comparison (Eq..IsNot) with its affinity and collation.
  Cmp(BinOp, Expr, Expr, CmpInfo)
  IsNull(Expr, Bool) // (expr, negated)
  Collate(Expr, Coll)
  Cast(Expr, Affinity)
  /// x [NOT] BETWEEN lo AND hi; infos for (x, lo) and (x, hi).
  Between(Expr, Expr, Expr, Bool, CmpInfo, CmpInfo)
  /// x [NOT] IN (list)
  InList(Expr, Array[Expr], Bool, CmpInfo)
  Like(glob~ : Bool, lhs~ : Expr, pat~ : Expr, esc~ : Expr?, neg~ : Bool)
  Case(
    base~ : Expr?,
    whens~ : Array[(Expr, Expr)],
    else_~ : Expr?,
    infos~ : Array[CmpInfo]
  )
  Func(
    name~ : String,
    args~ : Array[Expr],
    star~ : Bool,
    distinct~ : Bool,
    coll~ : Coll
  )
} derive(Debug)

///|
pub(all) enum Coll {
  CBinary
  CNoCase
  CRTrim
} derive(Eq, Debug)

///|
/// How a comparison converts and orders its operands.
pub(all) struct CmpInfo {
  aff : Affinity?
  coll : Coll
} derive(Debug)

///|
let default_info : CmpInfo = { aff: None, coll: CBinary, }

///|
pub(all) enum ResultCol {
  Star
  TableStar(String)
  ExprCol(Expr, String?)
} derive(Debug)

///|
pub(all) struct OrderTerm {
  expr : Expr
  desc : Bool
} derive(Debug)

///|
pub(all) enum FromItem {
  TableRef(name~ : String, alias~ : String?)
} derive(Debug)

///|
pub(all) struct Select {
  distinct : Bool
  cols : Array[ResultCol]
  from : Array[FromItem]
  where_ : Expr?
  order_by : Array[OrderTerm]
} derive(Debug)

///|
pub(all) enum Conflict {
  CRollback
  CAbort
  CFail
  CIgnore
  CReplace
} derive(Eq, Debug)

///|
pub(all) struct ColumnDef {
  name : String
  type_name : String
  affinity : Affinity
  mut not_null : Bool
  mut primary_key : Bool
  mut pk_desc : Bool
  mut autoincrement : Bool
  mut unique : Bool
  mut default_ : Expr?
  mut collate : String?
  checks : Array[Expr]
} derive(Debug)

///|
pub(all) enum TableConstraint {
  TPrimaryKey(Array[String], Conflict?)
  TUnique(Array[String], Conflict?)
  TCheck(Expr)
  TForeignKey
} derive(Debug)

///|
pub(all) enum InsertSource {
  Values(Array[Array[Expr]])
  SelectSrc(Select)
  DefaultValues
} derive(Debug)

///|
pub(all) enum Stmt {
  CreateTable(
    name~ : String,
    if_not_exists~ : Bool,
    cols~ : Array[ColumnDef],
    constraints~ : Array[TableConstraint],
    sql~ : String
  )
  DropTable(name~ : String, if_exists~ : Bool)
  Insert(
    table~ : String,
    cols~ : Array[String]?,
    src~ : InsertSource,
    or_~ : Conflict?
  )
  SelectStmt(Select)
} derive(Debug)
///|
pub(all) struct Row {
  rowid : Int64
  vals : Array[Value]
}

///|
pub(all) struct Table {
  name : String
  cols : Array[ColumnDef]
  constraints : Array[TableConstraint]
  rows : Array[Row]
  mut max_rowid : Int64
  sql : String
  rowid_alias : Int? // column that is an INTEGER PRIMARY KEY
}

///|
fn find_rowid_alias(
  cols : Array[ColumnDef],
  constraints : Array[TableConstraint],
) -> Int? {
  for i, c in cols {
    if c.primary_key && !c.pk_desc && c.type_name.to_upper() == "INTEGER" {
      return Some(i)
    }
  }
  for tc in constraints {
    if tc is TPrimaryKey(names, _) && names.length() == 1 {
      for i, c in cols {
        if same_name(c.name, names[0]) && c.type_name.to_upper() == "INTEGER" {
          return Some(i)
        }
      }
    }
  }
  None
}

