INSERT INTO t VALUES (1, 'other', 'upd') ON CONFLICT(id) DO UPDATE SET v = excluded.v;
SELECT changes(), last_insert_rowid();
-- DO NOTHING: no change.
INSERT INTO t VALUES (1, 'other', 'upd2') ON CONFLICT DO NOTHING;
