    Update(table~, alias~, or_~, sets~, where_~, returning~) =>
      self.run_update(table, alias, or_, sets, where_, returning)
    Delete(table~, alias~, where_~, returning~) =>
      self.run_delete(table, alias, where_, returning)
    _ => []
  }
