///|
pub(all) struct ColumnDef {
  name : String
  type_name : String
  affinity : Affinity
  mut not_null : Bool
  mut primary_key : Bool
  mut pk_desc : Bool
  mut autoincrement : Bool
  mut unique : Bool
  mut default_ : Expr?
  mut collate : String?
  checks : Array[Expr]
  mut pk_conflict : Conflict?
  mut nn_conflict : Conflict?
  mut unique_conflict : Conflict?
} derive(Debug)

///|
pub(all) enum TableConstraint {
  TPrimaryKey(Array[String], Conflict?)
  TUnique(Array[String], Conflict?)
  TCheck(Expr)
  TForeignKey
} derive(Debug)

///|
pub(all) enum InsertSource {
  Values(Array[Array[Expr]])
  SelectSrc(Select)
  DefaultValues
} derive(Debug)

///|
/// ON CONFLICT [(target)] DO NOTHING | DO UPDATE SET ... [WHERE ...]
pub(all) struct Upsert {
  target : Array[String]?
  sets : Array[(String, Expr)]? // None = DO NOTHING
  where_ : Expr?
} derive(Debug)

///|
pub(all) enum Stmt {
  CreateTable(
    name~ : String,
    if_not_exists~ : Bool,
    cols~ : Array[ColumnDef],
    constraints~ : Array[TableConstraint],
    sql~ : String
  )
  DropTable(name~ : String, if_exists~ : Bool)
  Insert(
    table~ : String,
    as_name~ : String?,
    cols~ : Array[String]?,
    src~ : InsertSource,
    or_~ : Conflict?,
    upserts~ : Array[Upsert],
    returning~ : Array[ResultCol]?
  )
  Update(
    table~ : String,
    as_name~ : String?,
    or_~ : Conflict?,
    sets~ : Array[(String, Expr)],
    where_~ : Expr?,
    returning~ : Array[ResultCol]?
  )
  Delete(
    table~ : String,
    as_name~ : String?,
    where_~ : Expr?,
    returning~ : Array[ResultCol]?
  )
  SelectStmt(Select)
} derive(Debug)
