// Tables, unique indexes and database state.

///|
/// An index over some columns of a table. Keys are the column values
/// followed by the rowid, so equal column values never collide in the map.
priv struct Index {
  name : String
  cols : Array[Int]
  colls : Array[Coll]
  unique : Bool
  conflict : Conflict?
  mut map : PMap[Array[Value], Int64]
}

///|
fn key_cmp(colls : Array[Coll]) -> (Array[Value], Array[Value]) -> Int {
  (a, b) => {
    let n = if a.length() < b.length() { a.length() } else { b.length() }
    for i in 0..<n {
      let coll = if i < colls.length() { colls[i] } else { CBinary }
      let c = compare_coll(a[i], b[i], coll)
      if c != 0 {
        return c
      }
    }
    a.length() - b.length()
  }
}

///|
fn Index::key_of(
  self : Index,
  vals : Array[Value],
  rowid : Int64,
) -> Array[Value] {
  let k : Array[Value] = Array(capacity=self.cols.length() + 1)
  for c in self.cols {
    k.push(vals[c])
  }
  k.push(Int(rowid))
  k
}

///|
/// Rowid of a row (other than `self_rowid`) whose indexed values equal
/// those of `vals`. Rows with a NULL in an indexed column never conflict.
fn Index::find_conflict(
  self : Index,
  vals : Array[Value],
  self_rowid : Int64?,
) -> Int64? {
  let n = self.cols.length()
  let key : Array[Value] = Array(capacity=n + 1)
  for c in self.cols {
    if vals[c] is Null {
      return None
    }
    key.push(vals[c])
  }
  key.push(Int(@int64.MIN_VALUE))
  let mut found : Int64? = None
  self.map.each_from(Some(key), (k, rid) => {
    for i in 0..<n {
      if compare_coll(k[i], key[i], self.colls[i]) != 0 {
        return false
      }
    }
    if self_rowid is Some(s) && s == rid {
      return true
    }
    found = Some(rid)
    false
  })
  found
}

///|
priv struct Table {
  name : String
  cols : Array[ColumnDef]
  constraints : Array[TableConstraint]
  sql : String
  rowid_alias : Int? // column that is an INTEGER PRIMARY KEY
  autoinc : Bool
  rowid_conflict : Conflict? // ON CONFLICT clause of the INTEGER PRIMARY KEY
  indexes : Array[Index] // in constraint-checking order
  checks : Array[Expr] // bound against the row layout [cols..., rowid]
  mut rows : PMap[Int64, Array[Value]]
  mut seq : Int64 // AUTOINCREMENT high-water mark
}

///|
fn rowid_cmp(a : Int64, b : Int64) -> Int {
  if a < b {
    -1
  } else if a > b {
    1
  } else {
    0
  }
}

///|
fn Table::insert_row(self : Table, rowid : Int64, vals : Array[Value]) -> Unit {
  self.rows = self.rows.add(rowid, vals)
  for ix in self.indexes {
    ix.map = ix.map.add(ix.key_of(vals, rowid), rowid)
  }
}

///|
fn Table::delete_row(self : Table, rowid : Int64) -> Unit {
  guard self.rows.find(rowid) is Some(vals) else { return }
  self.rows = self.rows.remove(rowid)
  for ix in self.indexes {
    ix.map = ix.map.remove(ix.key_of(vals, rowid))
  }
}

///|
fn find_rowid_alias(
  cols : Array[ColumnDef],
  constraints : Array[TableConstraint],
) -> Int? {
  for i, c in cols {
    if c.primary_key && !c.pk_desc && c.type_name.to_upper() == "INTEGER" {
      return Some(i)
    }
  }
  for tc in constraints {
    if tc is TPrimaryKey(names, _) && names.length() == 1 {
      for i, c in cols {
        if same_name(c.name, names[0]) && c.type_name.to_upper() == "INTEGER" {
          return Some(i)
        }
      }
    }
  }
  None
}

///|
fn col_index_in(cols : Array[ColumnDef], name : String) -> Int? {
  for i, c in cols {
    if same_name(c.name, name) {
      return Some(i)
    }
  }
  None
}

///|
/// Build a table from a CREATE TABLE statement.
fn build_table(
  name : String,
  cols : Array[ColumnDef],
  constraints : Array[TableConstraint],
  sql : String,
) -> Table raise SqlError {
  for i, c in cols {
    for j in 0..<i {
      if same_name(cols[j].name, c.name) {
        raise sql_err("duplicate column name: \{c.name}")
      }
    }
  }
  let rowid_alias = find_rowid_alias(cols, constraints)
  let mut autoinc = false
  let mut rowid_conflict : Conflict? = None
  for i, c in cols {
    if c.autoincrement {
      if rowid_alias != Some(i) {
        raise sql_err("AUTOINCREMENT is only allowed on an INTEGER PRIMARY KEY")
      }
      autoinc = true
    }
    if rowid_alias == Some(i) && c.primary_key {
      rowid_conflict = c.pk_conflict
    }
  }
  // unique indexes in creation order
  let created : Array[Index] = []
  fn add_index(
    idx_cols : Array[Int],
    conflict : Conflict?,
    is_pk : Bool,
  ) -> Unit {
    for ix in created {
      if ix.cols == idx_cols {
        return
      }
    }
    let colls = idx_cols.map(i => col_coll(cols[i]))
    let n = created.length() + 1
    created.push({
      name: "sqlite_autoindex_\{name}_\{n}",
      cols: idx_cols,
      colls,
      unique: true,
      conflict,
      map: PMap::empty(key_cmp(colls)),
    })
    ignore(is_pk)
  }

  for i, c in cols {
    if c.primary_key && rowid_alias != Some(i) {
      add_index([i], c.pk_conflict, true)
    }
    if c.unique {
      add_index([i], c.unique_conflict, false)
    }
  }
  for tc in constraints {
    match tc {
      TPrimaryKey(names, conflict) | TUnique(names, conflict) => {
        let idx_cols : Array[Int] = []
        for n in names {
          match col_index_in(cols, n) {
            Some(i) => idx_cols.push(i)
            None => raise sql_err("no such column: \{n}")
          }
        }
        if tc is TPrimaryKey(_, _) &&
          rowid_alias is Some(ai) &&
          idx_cols == [ai] {
          rowid_conflict = conflict
        } else {
          add_index(idx_cols, conflict, tc is TPrimaryKey(_, _))
        }
      }
      _ => ()
    }
  }
  created.rev_in_place()
  let t : Table = {
    name,
    cols,
    constraints,
    sql,
    rowid_alias,
    autoinc,
    rowid_conflict,
    indexes: created,
    checks: [],
    rows: PMap::empty(rowid_cmp),
    seq: 0L,
  }
  // bind CHECK constraints against the table's own row
  let scope : Scope = {
    sources: [{ name, table: t, offset: 0, hidden: false, }],
    aliases: [],
    agg: Non

///|
fn build_upsert_plan(
  t : Table,
  upserts : Array[Upsert],
) -> UpsertPlan? raise SqlError {
  if upserts.length() == 0 {
    return None
  }
  let by_constraint : Map[Int, Int] = Map([])
  let first : Array[Int] = []
  let mut catch_all : Int? = None
  for ui, u in upserts {
    match u.target {
      None => if catch_all is None { catch_all = Some(ui) }
      Some(names) => {
        let idxs : Array[Int] = []
        for n in names {
          match t.col_index(n) {
            Some(i) => idxs.push(i)
            None => raise sql_err("no such column: \{n}")
          }
        }
        let mut found : Int? = None
        if idxs.length() == 1 && t.rowid_alias == Some(idxs[0]) {
          found = Some(-1)
        } else {
          for i, ix in t.indexes {
            if same_col_set(ix.cols, idxs) {
              found = Some(i)
              break
            }
          }
        }
        guard found is Some(c) else {
          raise sql_err(
            "ON CONFLICT clause does not match any PRIMARY KEY or UNIQUE constraint",
          )
        }
        if !by_constraint.contains(c) {
          by_constraint[c] = ui
          first.push(c)
        }
      }
    }
  }
  Some({ by_constraint, catch_all, first, })
}

///|
/// Bind SET assignments: (column index or -1 for the rowid, expression).
fn bind_sets(
  t : Table,
  sets : Array[(String, Expr)],
  scope : Scope,
) -> Array[(Int, Expr)] raise SqlError {
  let out : Array[(Int, Expr)] = []
  for s in sets {
    let ci = match t.col_index(s.0) {
      Some(i) => i
      None =>
        if is_rowid_name(s.0) {
          -1
        } else {
          raise sql_err("no such column: \{s.0}")
        }
    }
    out.push((ci, scope.bind(s.1)))
  }
  out
}

///|
/// Apply SET assignments to a row; all right-hand sides see `env`.
fn apply_sets(
  t : Table,
  sets : Array[(Int, Expr)],
  oldvals : Array[Value],
  oldrowid : Int64,
  env : Array[Value],
) -> (Int64, Array[Value]) raise SqlError {
  let computed = sets.map(s => eval(s.1, env))
  let newvals = oldvals.copy()
  let mut rowid_v : Value? = None
  let mut alias_set = false
  for i, s in sets {
    if s.0 < 0 {
      rowid_v = Some(apply_affinity(computed[i], AffInteger))
    } else {
      newvals[s.0] = apply_affinity(computed[i], t.cols[s.0].affinity)
      if t.rowid_alias == Some(s.0) {
        alias_set = true
      }
    }
  }
  let mut newrowid = oldrowid
  if t.rowid_alias is Some(ai) && alias_set {
    match newvals[ai] {
      Int(i) => newrowid = i
      _ => raise sql_err("datatype mismatch")
    }
  }
  if rowid_v is Some(v) {
    match v {
      Int(i) => {
        newrowid = i
        if t.rowid_alias is Some(ai) {
          newvals[ai] = Int(i)
        }
      }
      _ => raise sql_err("datatype mismatch")
    }
  }
  (newrowid, newvals)
}

///|
fn single_scope(t : Table, as_name : String?) -> Scope {
  let name = match as_name {
    Some(a) => a
    None => t.name
  }
  {
    sources: [{ name, table: t, offset: 0, hidden: false, }],
    aliases: [],
    agg: None,
  }
}

///|
fn bind_returning(
  t : Table,
  scope : Scope,
  returning : Array[ResultCol]?,
) -> Array[Expr]? raise SqlError {
  guard returning is Some(cols) else { return None }
  let out : Array[Expr] = []
  for c in cols {
    match c {
      Star =>
        for i, cd in t.cols {
          out.push(Slot(i, cd.affinity, col_coll(cd)))
        }
      TableStar(_) =>
        raise sql_err("RETURNING may not use \"TABLE.*\" wildcards")
      ExprCol(e, _) => out.push(scope.bind(e))
    }
  }
  Some(out)
}

///|
fn row_with_rowid(vals : Array[Value], rowid : Int64) -> Array[Value] {
  let row = vals.copy()
  row.push(Int(rowid))
  row
}

///|
fn push_returning(
  out : Array[Array[Value]],
  ret : Array[Expr]?,
  vals : Array[Value],
  rowid : Int64,
) -> Unit raise SqlError {
  if ret is Some(exprs) {
    let row = row_with_rowid(vals, rowid)
    out.push(exprs.map(e => eval(e, row)))
  }
}

///|
fn Table::new_rowid(self : Table) -> Int64 raise SqlError {
  let mut base = self.rows.max_key().unwrap_or(0L)
  if self.autoinc && self.seq > base {
    base = self.seq
  }
  if base < @int64.MAX_VALUE {
    return base + 1L
  }
  if !self.autoinc {
    // like SQLite, fall back to a pseudo-random unused rowid
    for _ in 0..<100 {
      rng_state.val = rng_state.val * 6364136223846793005L +
        1442695040888963407L
      let cand = (rng_state.val >> 1) & @int64.MAX_VALUE
      if cand > 0L && self.rows.find(cand) is None {
        return cand
      }
    }
  }
  raise sql_err("database or disk is full")
}

