  self : Index,
  vals : Array[Value],
  rowid : Int64,
) -> Array[Value] {
  let k : Array[Value] = Array(capacity=self.cols.length() + 1)
  for c in self.cols {
    k.push(vals[c])
  }
  k.push(Int(rowid))
  k
}

