fn QPlan::cols(self : QPlan) -> Array[ColInfo] {
  match self {
    PSel(p) => p.names.mapi((i, n) => col_info_of(n, p.exprs[i]))
    PValues(rows) =>
      rows[0].mapi((i, _) => {
        name: "column\{i + 1}",
        aff: None,
        coll: None,
        explicit: false,
      })
    PComp(c) => c.cols
  }
}

