  self : Pager,
  root : Int,
  f : (Int64, Bytes) -> Unit raise SqlError,
) -> Unit raise SqlError {
  let stack = [root]
  let mut guard_count = 0
  while stack.pop() is Some(pgno) {
    guard_count += 1
    if guard_count > self.data.length() / 512 + 10 {
      raise sql_err("database disk image is malformed")
    }
    let base = self.page_off(pgno)
    let hdr = if pgno == 1 { base + 100 } else { base }
    let kind = self.u8(hdr)
    let ncells = self.u16(hdr + 3)
    match kind {
      0x0d => {
        let ptrs = hdr + 8
        for i in 0..<ncells {
          let c = base + self.u16(ptrs + 2 * i)
          let (plen, n1) = read_varint(self.data, c)
          let (rowid, n2) = read_varint(self.data, c + n1)
          f(rowid, self.payload(c + n1 + n2, plen.to_int(), true))
        }
      }
      0x05 => {
        let ptrs = hdr + 12
        // push in reverse so pages are visited in key order
        stack.push(self.u32(hdr + 8))
        for i = ncells - 1; i >= 0; i = i - 1 {
          let c = base + self.u16(ptrs + 2 * i)
          stack.push(self.u32(c))
        }
      }
      _ => raise sql_err("database disk image is malformed")
    }
  }
}

///|
fn be_int(data : Bytes, off : Int, n : Int) -> Int64 {
  let mut v = if data[off].to_int() >= 0x80 { -1L } else { 0L }
  for i in 0..<n {
    v = (v << 8) | data[off + i].to_int64()
  }
  v
}

///|
/// Decode a record into its values.
fn decode_record(data : Bytes) -> Array[Value] raise SqlError {
  let out : Array[Value] = []
  if data.length() == 0 {
    return out
  }
  let (hsize, n0) = read_varint(data, 0)
  let hend = hsize.to_int()
  let mut h = n0
  let mut b = hend
  while h < hend {
    let (st64, n) = read_varint(data, h)
    h += n
    let st = st64.to_int()
    let len = match st {
      0 | 8 | 9 => 0
      1 => 1
      2 => 2
      3 => 3
      4 => 4
      5 => 6
      6 | 7 => 8
      _ => if st >= 12 { (st - 12) / 2 } else { 0 }
    }
    if b + len > data.length() {
      raise sql_err("database disk image is malformed")
    }
    let v = match st {
      0 => Null
      1 | 2 | 3 | 4 | 5 | 6 => Int(be_int(data, b, len))
      7 => {
        let bits = be_int(data, b, 8)
        let d = bits.reinterpret_as_double()
        if d.is_nan() {
          Null
        } else {
          Real(d)
        }
      }
      8 => Int(0L)
      9 => Int(1L)
      _ =>
        if st >= 12 && st % 2 == 0 {
          Blob(data[b:b + len].to_owned())
        } else if st >= 13 {
          Text(@utf8.decode_lossy(data[b:b + len]))
        } else {
          Null
        }
    }
    out.push(v)
    b += len
  }
  out
}

///|
/// Load a database file image. An empty image is an empty database.
pub fn Database::load_file(self : Database, data : Bytes) -> Unit raise SqlError {
  if data.length() == 0 {
    return
  }
  if data.length() < 100 ||
    data[0:16].to_owned() != b"SQLite format 3\x00" {
    raise sql_err("file is not a database")
  }
  let ps = (data[16].to_int() << 8) | data[17].to_int()
  let page_size = if ps == 1 { 65536 } else { ps }
  let pager = { data, page_size, usable: page_size - data[20].to_int() }
  let entries : Array[Array[Value]] = []
  pager.scan_table(1, (_, p) => entries.push(decode_record(p)))
  let seqs : Array[(String, Int64)] = []

// Tables, unique indexes and database state.

///|
/// Definition of an explicit (CREATE INDEX) index, kept for rebinding.
priv struct IndexDef {
  cols : Array[IndexCol]
  where_ : Expr?
  sql : String
}

///|
/// An index over columns or expressions of a table. Keys are the key values
/// followed by the rowid, so equal key values never collide in the map.
priv struct Index {
  name : String
  exprs : Array[Expr] // key expressions bound against [cols..., rowid]
  cols : Array[Int] // column of each key part, -1 for an expression
  colls : Array[Coll]
  descs : Array[Bool]
  affs : Array[Affinity]
  unique : Bool
  conflict : Conflict?
  where_ : Expr? // partial index predicate (bound)
  def : IndexDef? // None for automatic indexes
  seq : Int // position in sqlite_schema
  mut map : PMap[Array[Value], Int64]
}

///|
fn key_cmp(colls : Array[Coll]) -> (Array[Value], Array[Value]) -> Int {
  (a, b) => {
    let n = if a.length() < b.length() { a.length() } else { b.length() }
    for i in 0..<n {
      let coll = if i < colls.length() { colls[i] } else { CBinary }
      let c = compare_coll(a[i], b[i], coll)
      if c != 0 {
        return c
      }
    }
    a.length() - b.length()
  }
}

///|
/// Index key order: like `key_cmp`, with DESC key parts reversed.
fn index_key_cmp(
  colls : Array[Coll],
  descs : Array[Bool],
) -> (Array[Value], Array[Value]) -> Int {
  (a, b) => {
    let n = if a.length() < b.length() { a.length() } else { b.length() }
    for i in 0..<n {
      let coll = if i < colls.length() { colls[i] } else { CBinary }
      let c = compare_coll(a[i], b[i], coll)
      if c != 0 {
        return if i < descs.length() && descs[i] { -c } else { c }
      }
    }
    a.length() - b.length()
  }
}

///|
/// Key values of a row (without the rowid); None if a partial index does
/// not cover the row.
fn Index::key_vals(
  self : Index,
  vals : Array[Value],
  rowid : Int64,
) -> Array[Value]? raise SqlError {
  let simple = self.where_ is None && self.cols.all(c => c >= 0)
  if simple {
    return Some(self.cols.map(c => vals[c]))
  }
  let row = vals.copy()
  row.push(Int(rowid))
  if self.where_ is Some(w) && !(eval(w, row).truth() is Some(true)) {
    return None
  }
  Some(self.exprs.map(e => eval(e, row)))
}

///|
fn Index::add_row(
  self : Index,
  vals : Array[Value],
  rowid : Int64,
) -> Unit raise SqlError {
  if self.key_vals(vals, rowid) is Some(k) {
    k.push(Int(rowid))
    self.map = self.map.add(k, rowid)
  }
}

///|
fn Index::remove_row(
  self : Index,
  vals : Array[Value],
  rowid : Int64,
) -> Unit raise SqlError {
  if self.key_vals(vals, rowid) is Some(k) {
    k.push(Int(rowid))
    self.map = self.map.remove(k)
  }
}

///|
/// Rowid of a row (other than `self_rowid`) whose key equals that of the
/// given row. Keys containing NULL never conflict.
fn Index::find_conflict(
  self : Index,
  vals : Array[Value],
  rowid : Int64,
  self_rowid : Int64?,
) -> Int64? raise SqlError {
  guard self.key_vals(vals, rowid) is Some(key) else { return None }
  let n = key.length()
  if key.any(v => v is Null) {
    return None
  }
  key.push(Int(@int64.MIN_VALUE))
  let mut found : Int64? = None
  self.map.each_from(Some(key), (k, rid) => {
    for i in 0..<n {
      if compare_coll(k[i], key[i], self.colls[i]) != 0 {
        return false
      }
    }
    if self_rowid is Some(s) && s == rid {
      return true
    }
    found = Some(rid)
    false
  })
  found
}

///|
priv struct Table {
  name : String
  cols : Array[ColumnDef]
  constraints : Array[TableConstraint]
  sql : String
  rowid_alias : Int? // column that is an INTEGER PRIMARY KEY
  autoinc : Bool
