}

///|
/// Splits a script into statements (SPEC §2.2). Pieces with only whitespace
/// and comments are dropped.
pub fn split_statements(s : String) -> Array[String] {
  let out : Array[String] = []
  let n = s.length()
  let mut i = 0
  let mut start = 0
  let mut has_content = false
  while i < n {
    let c = s[i]
    if c == '\'' || c == '"' || c == '`' {
      has_content = true
      let mut j = i + 1
      while j < n {
        if s[j] == c {
          if j + 1 < n && s[j + 1] == c {
            j += 2
            continue
          }
          break
        }
        j += 1
      }
      i = j + 1
    } else if c == '[' {
      has_content = true
      let mut j = i + 1
      while j < n && s[j] != ']' {
        j += 1
      }
      i = j + 1
    } else if c == '-' && i + 1 < n && s[i + 1] == '-' {
      while i < n && s[i] != '\n' {
        i += 1
      }
    } else if c == '/' && i + 1 < n && s[i + 1] == '*' {
      let mut j = i + 2
      while j < n && !(s[j] == '*' && j + 1 < n && s[j + 1] == '/') {
        j += 1
      }
      i = if j >= n { n } else { j + 2 }
    } else if c == ';' {
      if has_content {
        out.push(s[start:i].to_owned())
      }
      has_content = false
      i += 1
      start = i
    } else {
      if !is_space_cu(c) {
        has_content = true
      }
      i += 1
    }
  }
  if has_content && start < n {
    out.push(s[start:n].to_owned())
  }
  out
}
