/// Formats a double per SPEC §2.3.
pub fn format_real(d : Double) -> String {
  if d.is_nan() {
    return "NULL"
  }
  if d.is_inf() {
    return if d > 0.0 { "Inf" } else { "-Inf" }
  }
  if d == 0.0 {
    return "0.0"
  }
  let neg = d < 0.0
  let (digits, e) = shortest_digits(d.abs())
  let sb = StringBuilder()
  if neg {
    sb.write_char('-')
  }
  let n = digits.length()
  if e > -5 && e < 16 {
    if e < 0 {
      sb.write_string("0.")
      for _ in 0..<(-e - 1) {
        sb.write_char('0')
      }
      sb.write_string(digits)
    } else if e + 1 >= n {
      sb.write_string(digits)
      for _ in 0..<(e + 1 - n) {
        sb.write_char('0')
      }
      sb.write_string(".0")
    } else {
      sb.write_view(digits[0:e + 1])
      sb.write_char('.')
      sb.write_view(digits[e + 1:])
    }
  } else {
    sb.write_view(digits[0:1])
    sb.write_char('.')
    if n > 1 {
      sb.write_view(digits[1:])
    } else {
      sb.write_char('0')
    }
    sb.write_char('e')
    sb.write_char(if e < 0 { '-' } else { '+' })
    let ae = if e < 0 { -e } else { e }
    if ae < 10 {
      sb.write_char('0')
    }
    sb.write_string(ae.to_string())
  }
  sb.to_string()
}

