          } else if i == @int64.MIN_VALUE && j == -1L {
            Real(9223372036854775808.0)
          } else {
            Int(i / j)
          }
        Rem =>
          if j == 0L {
            Null
          } else if j == -1L {
            Int(0L)
          } else {
            Int(i % j)
          }
        _ => Null
