  let table = match self.find_table(ins.table) {
    Some(t) => t
    None => raise SqlError("no such table: \{ins.table}")
  }
  let ncols = table.columns.length()
  let width = ins.rows[0].length()
  for r in ins.rows {
    if r.length() != width {
      raise SqlError("all VALUES must have the same number of terms")
    }
  }
  let targets : Array[Int] = match ins.columns {
    Some(names) => {
      let out = []
      for n in names {
        match table.find_column(n) {
          Some(i) => out.push(i)
          None =>
            if is_rowid_name(n) {
              out.push(-1)
            } else {
              raise SqlError("table \{table.name} has no column named \{n}")
            }
        }
      }
      if width != out.length() {
        raise SqlError("\{width} values for \{out.length()} columns")
      }
      out
    }
    None => {
      if width != ncols {
        raise SqlError(
          "table \{table.name} has \{ncols} columns but \{width} valu

