  tok_is_kw(t, "NOT") ||
  tok_is_kw(t, "NULL") ||
  tok_is_kw(t, "UNIQUE") ||
  tok_is_kw(t, "CHECK") ||
  tok_is_kw(t, "DEFAULT") ||
  tok_is_kw(t, "COLLATE") ||
  tok_is_kw(t, "REFERENCES") ||
  tok_is_kw(t, "GENERATED") ||
  tok_is_kw(t, "AS")
}

