///|
pub fn Database::execute(
  self : Database,
  st : Stmt,
) -> Array[Array[Value]] raise SqlError {
  match st {
    CreateTableStmt(ct) => {
      self.create_table(ct)
      []
    }
    DropTableStmt(name, if_exists) => {
      match self.find_table(name) {
        Some(_) => self.remove_table(name)
        None => if !if_exists { raise SqlError("no such table: \{name}") }
      }
      []
    }
    InsertStmt(ins) => self.run_dml(() => self.insert(ins))
    UpdateStmt(up) => self.run_dml(() => self.update(up))
    DeleteStmt(del) => self.run_dml(() => self.delete(del))
    SelectStmt(sel) => self.select(sel)
  }
}

///|
/// Runs a data-changing statement, maintaining changes() counters.
fn Database::run_dml(
  self : Database,
  body : () -> Array[Array[Value]] raise SqlError,
) -> Array[Array[Value]] raise SqlError {
  self.stmt_changes = 0L
  self.keep_on_error = false
  let rows = {
    errdefer (if self.keep_on_error {
      conn.changes = self.stmt_changes
      conn.total_changes += self.stmt_changes
    } else {
      conn.changes = 0L
    })
    body()
  }
  conn.changes = self.stmt_changes
  conn.total_changes += self.stmt_changes
  rows
}

///|
/// Executes one statement atomically: on error its effects are undone
/// (unless a FAIL conflict asked to keep them).
pub fn Database::execute_atomic(
  self : Database,
  st : Stmt,
) -> Array[Array[Value]] raise SqlError {
  let mark = self.undo_mark()
  self.keep_on_error = false
  defer self.commit_all()
  errdefer (if !self.keep_on_error { self.rollback_to(mark) })
  self.execute(st)
}

