///|
fn Parser::func_call(self : Parser, name : String) -> Expr raise SqlError {
  let args : Array[Expr] = []
  let mut distinct = false
  let mut star = false
  if self.eat_op("*") {
    star = true
  } else if !self.is_op(")") {
    if self.eat_kw("DISTINCT") {
      distinct = true
    } else {
      ignore(self.eat_kw("ALL"))
    }
    while true {
      args.push(self.expr())
      if !self.eat_op(",") {
        break
      }
    }
  }
  self.expect_op(")")
  Func(name=name.to_lower(), args~, distinct~, star~)
}

