///|
/// Visits entries in key order until `f` returns false.
pub fn[K, V] OrdMap::each_while(
  self : OrdMap[K, V],
  f : (K, V) -> Bool raise?,
) -> Unit raise? {
  fn go(n : Node[K, V]) -> Bool raise? {
    match n {
      Leaf => true
      Branch(l, k, v, r, _) => go(l) && f(k, v) && go(r)
    }
  }

  ignore(go(self.root))
}

///|
/// Visits entries with key >= `lo` in key order until `f` returns false.
pub fn[K, V] OrdMap::each_from(
  self : OrdMap[K, V],
  lo : K,
  f : (K, V) -> Bool raise?,
) -> Unit raise? {
  let cmp = self.cmp
  fn go(n : Node[K, V]) -> Bool raise? {
    match n {
      Leaf => true
      Branch(l, k, v, r, _) =>
        if cmp(k, lo) < 0 {
          go(r)
        } else {
          go(l) && f(k, v) && go(r)
        }
    }
  }

  ignore(go(self.root))
}

///|
/// Visits entries in descending key order until `f` returns false.
pub fn[K, V] OrdMap::each_rev_while(
  self : OrdMap[K, V],
  f : (K, V) -> Bool raise?,
) -> Unit raise? {
  fn go(n : Node[K, V]) -> Bool raise? {
    match n {
      Leaf => true
      Branch(l, k, v, r, _) => go(r) && f(k, v) && go(l)
    }
  }

  ignore(go(self.root))
}

///|
pub fn[K, V] OrdMap::to_array(self : OrdMap[K, V]) -> Array[(K, V)] {
  let out = []
  self.each_while((k, v) => {
    out.push((k, v))
    true
  })
  out
}

///|
pub fn[K, V] OrdMap::values(self : OrdMap[K, V]) -> Array[V] {
  let out = []
  self.each_while((_, v) => {
    out.push(v)
    true
  })
  out
}
}

///|
/// True if a call with `n` arguments is an aggregate (min/max are scalar
/// with two or more arguments).
fn is_aggregate_call(name : String, n : Int) -> Bool {
  match name {
    "min" | "max" => n == 1
    _ => aggregate_arity.contains(name)
  }
}

///|
/// Bind-time validation of a function call.
fn check_function_call(
  name : String,
  args : Array[Expr],
) -> Unit raise SqlError {
  let n = args.length()
  if is_aggregate_call(name, n) {
    let (lo, hi) = aggregate_arity[name]
    if n < lo || n > hi {
      raise SqlError("wrong number of arguments to function \{name}()")
    }
    raise SqlError("misuse of aggregate function \{name}()")
  }
  guard function_arity.get(name) is Some((lo, hi)) else {
    raise SqlError("no such function: \{name}")
  }
  if n < lo || (hi >= 0 && n > hi) {
    raise SqlError("wrong number of arguments to function \{name}()")
  }
  if name == "likelihood" {
    let ok = match args[1] {
      Lit(Real(d)) => d >= 0.0 && d <= 1.0
      _ => false
    }
    if !ok {
      raise SqlError(
        "second argument to likelihood() must be a constant between 0.0 and 1.0",
      )
    }
  }
}

