///|
pub(all) struct Column {
  name : String
  decl_type : String
  aff : Affinity
  coll : String?
  def : ColumnDef
}

///|
/// A UNIQUE or (non-rowid) PRIMARY KEY constraint, with a hash of its keys.
pub(all) struct UniqueIndex {
  cols : Array[Int]
  colls : Array[String]
  conflict : Conflict
  is_pk : Bool
  keys : Map[String, Int64]
}

///|
pub(all) struct CheckCons {
  expr : Expr // bound against the table's own row
  label : String
}

///|
pub(all) struct Table {
  name : String
  columns : Array[Column]
  rows : OrdMap[Int64, Array[Value]]
  /// Index of the INTEGER PRIMARY KEY column (rowid alias), or -1.
  ipk : Int
  ipk_conflict : Conflict
  autoinc : Bool
  mut seq : Int64
  uniques : Array[UniqueIndex]
  checks : Array[CheckCons]
}

///|
priv enum Undo {
  UInsert(Table, Int64)
  UDelete(Table, Int64, Array[Value])
  USeq(Table, Int64)
  UCreate(String)
  UDrop(String, Table)
}

///|
pub(all) struct Database {
  tables : Map[String, Table]
  priv undo : Array[Undo]
  /// Set when a FAIL conflict aborts a statement: its changes are kept.
  mut keep_on_error : Bool
  /// Rows changed by the current statement.
  mut stmt_changes : Int64
}

///|
priv struct ConnState {
  mut last_rowid : Int64
  mut changes : Int64
  mut total_changes : Int64
}

///|
let conn : ConnState = { last_rowid: 0L, changes: 0L, total_changes: 0L, }

///|
pub fn Database::new() -> Database {
  { tables: Map([]), undo: [], keep_on_error: false, stmt_changes: 0L, }
}

///|
pub fn name_key(s : String) -> String {
  s.to_lower()
}

///|
pub fn Database::find_table(self : Database, name : String) -> Table? {
  self.tables.get(name_key(name))
}

///|
pub fn Table::find_column(self : Table, name : String) -> Int? {
  for i, c in self.columns {
    if c.name.equal_ignore_ascii_case(name) {
      return Some(i)
    }
  }
  None
}

///|
fn int64_cmp(a : Int64, b : Int64) -> Int {
  if a < b {
    -1
  } else if a > b {
    1
  } else {
    0
  }
}

///|
fn new_rows() -> OrdMap[Int64, Array[Value]] {
  OrdMap::new(int64_cmp)
}

// ---------------------------------------------------------------------------
// Unique keys
// ---------------------------------------------------------------------------

///|
/// Canonical text of a value for equality under a collation; numerically
/// equal INTEGER and REAL values get the same key.
fn value_key(sb : StringBuilder, v : Value, coll : String) -> Unit {
  match v {
    Null => sb.write_string("N")
    Int(i) => sb.write_string("I\{i}")
    Real(d) =>
      match real_to_int_exact(d) {
        Some(i) => sb.write_string("I\{i}")
        None => sb.write_string("R\{d.reinterpret_as_uint64()}")
      }
    Text(s) => {
      let t = match coll {
        "NOCASE" => {
          let b = StringBuilder()
          for c in s {
            b.write_char(lower_ascii_char(c))
          }
          b.to_string()
        }
        "RTRIM" => rtrim_spaces(s).to_owned()
        _ => s
      }
      sb.write_string("T\{t.length()}:")
      sb.write_string(t)
    }
    Blob(b) => sb.write_string("B" + blob_to_hex(b))
  }
  sb.write_char('|')
}

///|
/// Key of a row in a unique index; None when a column is NULL (NULLs never
/// conflict).
fn UniqueIndex::key_of(self : UniqueIndex, vals : Array[Value]) -> String? {
  let sb = StringBuilder()
  for k, ci in self.cols {
    let v = vals[ci]
    if v is Null {
      return None
    }
    value_key(sb, v, self.colls[k])
  }
  Some(sb.to_string())
}

///|
fn Table::constraint_label(self : Table, u : UniqueIndex) -> String {
  u.cols.map(ci => self.name + "." + self.columns[ci].name).join(", ")
}

///|
fn Table::rowid_label(self : Table) -> String {
  if self.ipk >= 0 {
    self.name + "." + self.columns[self.ipk].name
  } else {
    self.name + ".rowid"
  }
}

// ---------------------------------------------------------------------------
// Raw row operations (maintain unique indexes, not logged)
// ---------------------------------------------------------------------------

///|
fn Table::raw_insert(self : Table, rowid : Int64, vals : Array[Value]) -> Unit {
  self.rows.set(rowid, vals)
  for u in self.uniques {
    if u.key_of(vals) is Some(k) {
      u.keys[k] = rowid
    }
  }
}

///|
fn Table::raw_delete(self : Table, rowid : Int64) -> Array[Value]? {
  guard self.rows.get(rowid) is Some(vals) else { return None }
  for u in self.uniques {
    if u.key_of(vals) is Some(k) && u.keys.get(k) == Some(rowid) {
      u.keys.remove(k)
    }
  }
  self.rows.remove(rowid)
  Some(vals)
}

// ---------------------------------------------------------------------------
// Logged operations and statement atomicity
// ---------------------------------------------------------------------------

///|
fn Database::insert_row(
  self : Database,
  t : Table,
  rowid : Int64,
  vals : Array[Value],
) -> Unit {
  t.raw_insert(rowid, vals)
  self.undo.push(UInsert(t, rowid))
  if t.autoinc && rowid > t.seq {
    self.undo.push(USeq(t, t.seq))
    t.seq = rowid
  }
}

///|
/// Logs an insertion done with `raw_insert` (no AUTOINCREMENT bump).
fn Database::log_insert(self : Database, t : Table, rowid : Int64) -> Unit {
  self.undo.push(UInsert(t, rowid))
}

///|
fn Database::delete_row(self : Database, t : Table, rowid : Int64) -> Unit {
  if t.raw_delete(rowid) is Some(vals) {
    self.undo.push(UDelete(t, rowid, vals))
  }
}

///|
fn Database::add_table(self : Database, t : Table) -> Unit {
  self.tables[name_key(t.name)] = t
  self.undo.push(UCreate(name_key(t.name)))
}

///|
fn Database::remove_table(self : Database, name : String) -> Unit {
  let key = name_key(name)
  if self.tables.get(key) is Some(t) {
    self.tables.remove(key)
    self.undo.push(UDrop(key, t))
  }
}

///|
fn Database::rollback_to(self : Database, mark : Int) -> Unit {
  while self.undo.length() > mark {
    match self.undo.pop() {
      Some(UInsert(t, rowid)) => ignore(t.raw_delete(rowid))
      Some(UDelete(t, rowid, vals)) => t.raw_insert(rowid, vals)
      Some(USeq(t, s)) => t.s

///|
priv struct Source {
  name : String
  /// Column metadata (a pseudo-table for subqueries in FROM).
  table : Table
  offset : Int
  /// Only reachable through a qualified name (upsert's `excluded`).
  hidden : Bool
  /// A subquery in FROM providing the rows.
  sub : Prepared?
  /// Join operator connecting this source to the ones on its left.
  kind : JoinKind
  /// ON condition (including USING/NATURAL equalities), bound.
  mut on : Expr?
  /// Columns merged into a left column by USING/NATURAL: hidden from
  /// unqualified references and `*`.
  merged : Array[Bool]
  /// Expressions used instead of the column for unqualified references
  /// (coalesced USING columns of RIGHT/FULL joins).
  overrides : Map[Int, Expr]
}

///|
fn new_source(
  name : String,
  table : Table,
  offset : Int,
  hidden? : Bool = false,
  sub? : Prepared,
  kind? : JoinKind = JInner,
) -> Source {
  {
    name,
    table,
    offset,
    hidden,
    sub,
    kind,
    on: None,
    merged: Array::make(table.columns.length(), false),
    overrides: Map([]),
  }
}

///|
priv struct Scope {
  sources : Array[Source]
  parent : Scope?
  /// Result-column aliases usable as a fallback (ORDER BY).
  aliases : Array[(String, Expr)]
  /// Set when a name resolves beyond this query (shared by all scopes of
  /// one query).
  correlated : Ref[Bool]
  /// Aggregates of this query, when it is an aggregate query (shared).
  agg_ctx : Ref[AggCtx?]
}

///|
fn new_scope(
  sources : Array[Source],
  parent : Scope?,
  aliases? : Array[(String, Expr)] = [],
  correlated? : Ref[Bool] = { val: false, },
  agg_ctx? : Ref[AggCtx?] = { val: None, },
) -> Scope {
  { sources, parent, aliases, correlated, agg_ctx, }
}

///|
fn bind_column(
  scope : Scope?,
  tbl : String?,
  name : String,
  dq : Bool,
) -> Expr raise SqlError {
  let mut depth = 0
  let mut sc = scope
  while sc is Some(s) {
    let mut found : Expr? = None
    for src in s.sources {
      match tbl {
        Some(t) => if !src.name.equal_ignore_ascii_case(t) { continue }
        None => if src.hidden { continue }
      }
      match src.table.find_column(name) {
        Some(i) => {
          if tbl is None && src.merged[i] {
            continue
          }
          if found is Some(_) {
            raise SqlError("ambiguous column name: \{name}")
          }
          let c = src.table.columns[i]
          found = match src.overrides.get(i) {
            Some(o) if tbl is None => Some(shift_depth(o, depth))
            _ => Some(Slot(depth~, idx=src.offset + i, aff=c.aff, coll=c.coll))
          }
        }
        None =>
          if is_rowid_name(name) && src.sub is None {
            if found is None {
              found = Some(
                Slot(
                  depth~,
                  idx=src.offset + src.table.columns.length(),
                  aff=AffInteger,
                  coll=None,
                ),
              )
            }
          }
      }
    }
    if found is Some(f) {
      return f
    }
    if tbl is None && depth == 0 {
      for a in s.aliases {
        if a.0.equal_ignore_ascii_case(name) {
          return a.1
        }
      }
    }
    s.correlated.val = true
    depth += 1
    sc = s.parent
  }
  if dq && tbl is None {
    return Lit(Text(name))
  }
  match tbl {
    Some(t) => raise SqlError("no such column: \{t}.\{name}")
    None => raise SqlError("no such column: \{name}")
  }
}

///|
fn is_rowid_name(n : String) -> Bool {
  n.equal_ignore_ascii_case("rowid") ||
  n.equal_ignore_ascii_case("oid") ||
  n.equal_ignore_ascii_case("_rowid_")
}

