///|
fn Parser::create_index(self : Parser, unique : Bool) -> CreateIndex raise SqlError {
  let if_not_exists = self.if_not_exists()
  let name = self.qualified_name()
  self.expect_kw("ON")
  let table = self.name()
  self.expect_op("(")
  let parts : Array[IndexPart] = []
  while true {
    let mut e = self.expr()
    let mut coll : String? = None
    while e is Collate(inner, c) {
      if coll is None {
        coll = Some(c)
      }
      e = inner
    }
    let mut desc = false
    if self.eat_kw("DESC") {
      desc = true
    } else {
      ignore(self.eat_kw("ASC"))
    }
    parts.push({ expr: e, coll, desc })
    if !self.eat_op(",") {
      break
    }
  }
  self.expect_op(")")
  let where_ = if self.eat_kw("WHERE") { Some(self.expr()) } else { None }
  { name, table, unique, if_not_exists, parts, where_, sql: self.src }
}

