fn Index::scan(
  self : Index,
  prefix : Array[Value],
  lo : (Value, Bool)?,
  hi : (Value, Bool)?,
  f : (Int64) -> Bool raise SqlError,
) -> Unit raise SqlError {
  let n = self.cols.length()
  let m = prefix.length()
  let desc = m < n && self.descs[m]
