///|
priv struct Source {
  name : String
  /// Column metadata (a pseudo-table for subqueries in FROM).
  table : Table
  offset : Int
  /// Only reachable through a qualified name (upsert's `excluded`).
  hidden : Bool
  /// A subquery in FROM providing the rows.
  sub : Prepared?
  /// Join operator connecting this source to the ones on its left.
  kind : JoinKind
  /// ON condition (including USING/NATURAL equalities), bound.
  mut on : Expr?
  /// Columns merged into a left column by USING/NATURAL: hidden from
  /// unqualified references and `*`.
  merged : Array[Bool]
  /// Expressions used instead of the column for unqualified references
  /// (coalesced USING columns of RIGHT/FULL joins).
  overrides : Map[Int, Expr]
}

///|
fn new_source(
  name : String,
  table : Table,
  offset : Int,
  hidden? : Bool = false,
  sub? : Prepared,
  kind? : JoinKind = JInner,
) -> Source {
  {
    name,
    table,
    offset,
    hidden,
    sub,
    kind,
    on: None,
    merged: Array::make(table.columns.length(), false),
    overrides: Map([]),
  }
}

///|
priv struct Scope {
  sources : Array[Source]
  parent : Scope?
  /// Result-column aliases usable as a fallback (ORDER BY).
  aliases : Array[(String, Expr)]
  /// Set when a name resolves beyond this query (shared by all scopes of
  /// one query).
  correlated : Ref[Bool]
  /// Aggregates of this query, when it is an aggregate query (shared).
  agg_ctx : Ref[AggCtx?]
}

///|
fn new_scope(
  sources : Array[Source],
  parent : Scope?,
  aliases? : Array[(String, Expr)] = [],
  correlated? : Ref[Bool] = { val: false, },
  agg_ctx? : Ref[AggCtx?] = { val: None, },
) -> Scope {
  { sources, parent, aliases, correlated, agg_ctx, }
}

///|
fn bind_column(
  scope : Scope?,
  tbl : String?,
  name : String,
  dq : Bool,
) -> Expr raise SqlError {
  let mut depth = 0
  let mut sc = scope
  while sc is Some(s) {
    let mut found : Expr? = None
    for src in s.sources {
      match tbl {
        Some(t) => if !src.name.equal_ignore_ascii_case(t) { continue }
        None => if src.hidden { continue }
      }
      match src.table.find_column(name) {
        Some(i) => {
          if tbl is None && src.merged[i] {
            continue
          }
          if found is Some(_) {
            raise SqlError("ambiguous column name: \{name}")
          }
          let c = src.table.columns[i]
          found = match src.overrides.get(i) {
            Some(o) if tbl is None => Some(shift_depth(o, depth))
            _ => Some(Slot(depth~, idx=src.offset + i, aff=c.aff, coll=c.coll))
          }
        }
        None =>
          if is_rowid_name(name) && src.sub is None {
            if found is None {
              found = Some(
                Slot(
                  depth~,
                  idx=src.offset + src.table.columns.length(),
                  aff=AffInteger,
                  coll=None,
                ),
              )
            }
          }
      }
    }
    if found is Some(f) {
      return f
    }
    if tbl is None && depth == 0 {
      for a in s.aliases {
        if a.0.equal_ignore_ascii_case(name) {
          return a.1
        }
      }
    }
    s.correlated.val = true
    depth += 1
    sc = s.parent
  }
  if dq && tbl is None {
    return Lit(Text(name))
  }
  match tbl {
    Some(t) => raise SqlError("no such column: \{t}.\{name}")
    None => raise SqlError("no such column: \{name}")
  }
}

///|
fn is_rowid_name(n : String) -> Bool {
  n.equal_ignore_ascii_case("rowid") ||
  n.equal_ignore_ascii_case("oid") ||
  n.equal_ignore_ascii_case("_rowid_")
}

///|
fn bind_expr(e : Expr, scope : Scope?) -> Expr raise SqlError {
  match e {
    Lit(_) | Slot(..) => e
    Col(tbl~, name~, dq~) => bind_column(scope, tbl, name, dq)
    Unary(op, x) => Unary(op, bind_expr(x, scope))
    Binary(op, l, r) => Binary(op, bind_expr(l, scope), bind_expr(r, scope))
    IsNull(x, n) => IsNull(bind_expr(x, scope), n)
    Is(l, r, n) => Is(bind_expr(l, scope), bind_expr(r, scope), n)
    Between(x, lo, hi, n) =>
      Between(
        bind_expr(x, scope),
        bind_expr(lo, scope),
        bind_expr(hi, scope),
        n,
      )
    InList(x, items, n) =>
      InList(bind_expr(x, scope), items.map(i => bind_expr(i, scope)), n)
    Like(op, x, p, esc, n) =>
      Like(
        op,
        bind_expr(x, scope),
        bind_expr(p, scope),
        match esc {
          Some(z) => Some(bind_expr(z, scope))
          None => None
        },
        n,
      )
    Func(name~, args~, distinct~, star~, filter~, order~) => {
      if is_aggregate_call(name, args.length()) &&
        outer_aggregate(e, scope) is Some(r) {
        return r
      }
      check_function_call(name, args)
      if filter is Some(_) {
        raise SqlError("FILTER may not be used with non-aggregate \{name}()")
      }
      if order.length() > 0 {
        raise SqlError("ORDER BY may not be used with non-aggregate \{name}()")
      }
      Func(
        name~,
        args=args.map(a => bind_expr(a, scope)),
        distinct~,
        star~,
        filter~,
        order~,
      )
    }
    AggRef(..) => e
    Case(base, whens, els) =>
      Case(
        match base {
          Some(b) => Some(bind_expr(b, scope))
          None => None
        },
        whens.map(w => (bind_expr(w.0, scope), bind_expr(w.1, scope))),
        match els {
          Some(x) => Some(bind_expr(x, scope))
          None => None
        },
      )
    Cast(x, t) => Cast(bind_expr(x, scope), t)
    Collate(x, c) => Collate(bind_expr(x, scope), check_collation(c))
    Subquery(sel) => {
      let p = cur_db().prepare_query(sel, scope)
      p.expect_one_column()
      ScalarQ(p.to_subquery())
    }
    Exists(sel) => ExistsQ(cur_db().prepare_query(sel, scope).to_subquery())
    InSelect(x, sel, n) => {
      let bx = bind_expr(x, scope)
      let p = cur_db().prepare_query(sel, scope)
      p.expect_one_column()
      InQ(bx, p.to_subquery(), n)
    }
    ScalarQ(_) | ExistsQ(_) | InQ(_,

  }
}

///|
fn Parser::statement(self : Parser) -> Stmt raise SqlError {
  if self.is_kw("SELECT") || self.is_kw("VALUES") {
    return SelectStmt(self.select())
  }
  if self.eat_kw("CREATE") {
    if self.eat_kw("TABLE") {
      return CreateTableStmt(self.create_table())
    }
    if self.eat_kw("UNIQUE") {
      self.expect_kw("INDEX")
      return CreateIndexStmt(self.create_index(true))
    }
    if self.eat_kw("INDEX") {
      return CreateIndexStmt(self.create_index(false))
    }
    if self.eat_kw("VIEW") {
      return CreateViewStmt(self.create_view())
    }
    raise self.syntax_error()
  }
  if self.eat_kw("DROP") {
    let kind = if self.eat_kw("TABLE") {
      0
    } else if self.eat_kw("INDEX") {
      1
    } else if self.eat_kw("VIEW") {
      2
    } else {
      raise self.syntax_error()
    }
    let mut if_exists = false
    if self.eat_kw("IF") {
      self.expect_kw("EXISTS")
      if_exists = true
    }
    let name = self.qualified_name()
    return match kind {
      0 => DropTableStmt(name, if_exists)
      1 => DropIndexStmt(name, if_exists)
      _ => DropViewStmt(name, if_exists)
    }
  }
  if self.eat_kw("ALTER") {
    self.expect_kw("TABLE")
    let name = self.qualified_name()
    if self.eat_kw("RENAME") {
      if self.eat_kw("TO") {
        return AlterStmt(name, RenameTo(self.name()))
      }
      ignore(self.eat_kw("COLUMN"))
      let old = self.name()
      self.expect_kw("TO")
      return AlterStmt(name, RenameColumn(old, self.name()))
    }
    if self.eat_kw("ADD") {
      ignore(self.eat_kw("COLUMN"))
      return AlterStmt(name, AddColumn(self.column_def()))
    }
    if self.eat_kw("DROP") {
      ignore(self.eat_kw("COLUMN"))
      return AlterStmt(name, DropColumn(self.name()))
    }
    raise self.syntax_error()
  }
  if self.eat_kw("BEGIN") {
    if !self.eat_kw("DEFERRED") && !self.eat_kw("IMMEDIATE") {
      ignore(self.eat_kw("EXCLUSIVE"))
    }
    if self.eat_kw("TRANSACTION") && self.is_name() {
      ignore(self.advance())
    }
    return BeginStmt
  }
  if self.eat_kw("COMMIT") || self.eat_kw("END") {
    if self.eat_kw("TRANSACTION") && self.is_name() {
      ignore(self.advance())
    }
    return CommitStmt
  }
  if self.eat_kw("ROLLBACK") {
    if self.eat_kw("TRANSACTION") && self.is_name() && !self.is_kw("TO") {
      ignore(self.advance())
    }
    if self.eat_kw("TO") {
      ignore(self.eat_kw("SAVEPOINT"))
      return RollbackStmt(Some(self.name()))
    }
    return RollbackStmt(None)
  }
  if self.eat_kw("SAVEPOINT") {
    return SavepointStmt(self.name())
  }
  if self.eat_kw("RELEASE") {
    ignore(self.eat_kw("SAVEPOINT"))
    return ReleaseStmt(self.name())
  }
  if self.eat_kw("INSERT") {
    let mut oc = CDefault
    if self.eat_kw("OR") {
      oc = self.conflict_algo()
    }
    return InsertStmt(self.insert(oc))
  }
  if self.eat_kw("REPLACE") {
    return InsertStmt(self.insert(CReplace))
  }
  if self.eat_kw("UPDATE") {
    return UpdateStmt(self.update())
  }
  if self.eat_kw("DELETE") {
    return DeleteStmt(self.delete())
  }
  raise self.syntax_error()
}

///|
fn Parser::if_not_exists(self : Parser) -> Bool raise SqlError {
