///|
/// The first explicit COLLATE found in the expression tree (SQLite's
/// EP_Collate propagation).
fn explicit_coll(e : Expr) -> String? {
  match e {
    Collate(_, c) => Some(c)
    Lit(_) | Col(..) | Slot(..) => None
    Subquery(_) | Exists(_) | ScalarQ(_) | ExistsQ(_) => None
    InSelect(x, _, _) | InQ(x, _, _) => explicit_coll(x)
    AggRef(coll~, ..) => coll
    Unary(_, x) | Cast(x, _) | IsNull(x, _) => explicit_coll(x)
    Binary(_, l, r) | Is(l, r, _) => first_explicit([l, r])
    Between(x, lo, hi, _) => first_explicit([x, lo, hi])
    InList(x, items, _) => {
      if explicit_coll(x) is Some(c) {
        return Some(c)
      }
      first_explicit(items)
    }
    Like(_, x, p, esc, _) => {
      if explicit_coll(p) is Some(c) {
        return Some(c)
      }
      if explicit_coll(x) is Some(c) {
        return Some(c)
      }
      match esc {
        Some(z) => explicit_coll(z)
        None => None
      }
    }
    Func(args~, ..) => first_explicit(args)
    Case(base, whens, els) => {
      if base is Some(b) && explicit_coll(b) is Some(c) {
        return Some(c)
      }
      for w in whens {
        if explicit_coll(w.0) is Some(c) {
          return Some(c)
        }
        if explicit_coll(w.1) is Some(c) {
          return Some(c)
        }
      }
      match els {
        Some(x) => explicit_coll(x)
          }
        Null => Null
      }
  }
}

///|
/// True if the expression refers to no columns.
fn is_constant_expr(e : Expr) -> Bool {
  match e {
    Lit(_) => true
    Col(..) | Slot(..) | AggRef(..) => false
    Subquery(_)
    | Exists(_)
    | InSelect(_, _, _)
    | ScalarQ(_)
    | ExistsQ(_)
    | InQ(_, _, _) => false
    Unary(_, x) | Cast(x, _) | Collate(x, _) | IsNull(x, _) =>
      is_constant_expr(x)
    Binary(_, l, r) | Is(l, r, _) => is_constant_expr(l) && is_constant_expr(r)
    Between(x, lo, hi, _) =>
      is_constant_expr(x) && is_constant_expr(lo) && is_constant_expr(hi)
    InList(x, items, _) => is_constant_expr(x) && items.all(is_constant_expr)
    Like(_, x, p, esc, _) =>
      is_constant_expr(x) &&
      is_constant_expr(p) &&
      (match esc {
        Some(z) => is_constant_expr(z)
        None => true
      })
    Func(args~, ..) => args.all(is_constant_expr)
    Case(base, whens, els) =>
      (match base {
        Some(b) => is_constant_expr(b)
        None => true
      }) &&
      whens.all(w => is_constant_expr(w.0) && is_constant_expr(w.1)) &&
      (match els {
        Some(z) => is_constant_expr(z)
        None => true
      })
  }
}
