      Text(s) => {
        let b = @utf8.encode(s[:])
        types.push((b.length() * 2 + 13).to_int64())
        body.write_bytes(b[:])
      }
      Blob(b) => {
        types.push((b.length() * 2 + 12).to_int64())
        body.write_bytes(b[:])
      }
