  let mut hlen = 0
  for t in types {
    hlen += varint_len(t)
  }
  let mut hsize = hlen + 1
  if varint_len(hsize.to_int64()) > 1 {
    hsize = hlen + varint_len((hlen + 2).to_int64())
    if varint_len(hsize.to_int64()) + hlen != hsize {
      hsize = hlen + varint_len(hsize.to_int64())
    }
  }
  let out = @buffer.Buffer(size_hint=hsize + body.length())
  write_varint(out, hsize.to_int64())
  for t in types {
    write_varint(out, t)
  }
  out.write_bytes(body.to_bytes()[:])
  out.to_bytes()
}

