      }
    } else {
      sb.write_string("0.")
      for _ in 0..<(-e - 1) {
        sb.write_char('0')
      }
      sb.write_string(digits)
    }
  } else {
    sb.write_view(digits[0:1])
    sb.write_char('.')
    if digits.length() > 1 {
      sb.write_view(digits[1:])
    } else {
      sb.write_char('0')
    }
    sb.write_char('e')
    sb.write_char(if e < 0 { '-' } else { '+' })
    let ae = if e < 0 { -e } else { e }
    if ae < 10 {
      sb.write_char('0')
    }
    sb.write_string(ae.to_string())
  }
  sb.to_string()
