///|
pub(all) struct TableColumn {
  name : String
  type_name : String
  affinity : Affinity
  def : ColumnDef
}

///|
pub(all) struct Table {
  name : String
  columns : Array[TableColumn]
  constraints : Array[TableConstraint]
  rows : @sorted_map.SortedMap[Int64, Array[Value]]
  mut max_rowid : Int64
}

///|
pub(all) struct Database {
  tables : Map[String, Table]
}

///|
pub fn Database::new() -> Database {
  { tables: Map([]) }
}

///|
pub fn fold_name(s : String) -> String {
  s.to_lower()
}

///|
pub fn Database::find_table(self : Database, name : String) -> Table? {
  self.tables.get(fold_name(name))
}

///|
pub fn Database::get_table(self : Database, name : String) -> Table raise SqlError {
  match self.find_table(name) {
    Some(t) => t
    None => raise err("no such table: " + name)
  }
}

///|
pub fn Table::column_index(self : Table, name : String) -> Int? {
  let f = fold_name(name)
  for i, c in self.columns {
    if fold_name(c.name) == f {
      return Some(i)
    }
  }
  None
}

///|
pub fn Table::insert_row(self : Table, row : Array[Value]) -> Int64 {
  let id = self.max_rowid + 1L
  self.max_rowid = id
  self.rows.set(id, row)
  id
}

///|
/// Result of executing one statement.
pub(all) struct QueryResult {
  columns : Array[String]
  rows : Array[Array[Value]]
}

///|
pub fn Database::execute(self : Database, sql : String) -> QueryResult raise SqlError {
  let stmt = parse_statement(sql)
  match stmt {
    CreateTableStmt(ct) => {
      self.create_table(ct)
      { columns: [], rows: [] }
    }
    DropTableStmt(name, if_exists) => {
      match self.find_table(name) {
        Some(_) => self.tables.remove(fold_name(name))
        None => if !if_exists { raise err("no such table: " + name) }
      }
      { columns: [], rows: [] }
    }
    InsertStmt(ins) => {
      self.insert(ins)
      { columns: [], rows: [] }
    }
    SelectStmt(sel) => self.run_select(sel)
  }
}

///|
fn Database::create_table(self : Database, ct : CreateTable) -> Unit raise SqlError {
  if self.find_table(ct.name) is Some(_) {
    if ct.if_not_exists {
      return
    }
    raise err("table " + ct.name + " already exists")
  }
  let seen : Set[String] = Set([])
  let columns = []
  for cd in ct.columns {
    if !seen.add_and_check(fold_name(cd.name)) {
      raise err("duplicate column name: " + cd.name)
    }
    columns.push({
      name: cd.name,
      type_name: cd.type_name,
      affinity: affinity_of_type(cd.type_name),
      def: cd,
    })
  }
  self.tables[fold_name(ct.name)] = {
    name: ct.name,
    columns,
    constraints: ct.constraints,
    rows: @sorted_map.SortedMap([]),
    max_rowid: 0L,
  }
}

///|
fn Database::insert(self : Database, ins : Insert) -> Unit raise SqlError {
  let table = self.get_table(ins.table)
  let ncols = table.columns.length()
  // Map each supplied value position to a table column index.
  let targets : Array[Int] = match ins.columns {
    Some(names) =>
      names.map(n => match table.column_index(n) {
        Some(i) => i
        None => raise err("table " + table.name + " has no column named " + n)
      })
    None => Array::makei(ncols, i => i)
  }
  let source_rows : Array[Array[Value]] = match ins.source {
    InsValues(rows) => {
      let scope = Scope::empty()
      let out = []
      for r in rows {
        if r.length() != targets.length() {
          if ins.columns is Some(_) {
            raise err(
              "\{r.length()} values for \{targets.length()} columns",
            )
          } else {
            raise err(
              "table \{table.name} has \{ncols} columns but \{r.length()} values were supplied",
            )
          }
        }
        let bound = r.map(e => bind_expr(self, scope, e))
        out.push(bound.map(b => eval(b, [])))
      }
      out
    }
    InsSelect(sel) => {
      let res = self.run_select(sel)
      if res.columns.length() != targets.length() {
        raise err(
          "table \{table.name} has \{ncols} columns but \{res.columns.length()} values were supplied",
        )
      }
      res.rows
    }
    InsDefault => [[]]
  }
  let new_rows = []
  for src in source_rows {
    let row = Array::make(ncols, Null)
    for k, ci in targets {
      if k < src.length() {
        row[ci] = src[k]
      }
    }
    for i in 0..<ncols {
      row[i] = row[i].apply_affinity(table.columns[i].affinity)
    }
    new_rows.push(row)
  }
  for row in new_rows {
    table.insert_row(row) |> ignore
  }
}
