///|
pub(all) struct ScopeTable {
  name : String
  columns : Array[TableColumn]
  offset : Int
}

///|
pub(all) struct Scope {
  tables : Array[ScopeTable]
  width : Int
}

///|
pub fn Scope::empty() -> Scope {
  { tables: [], width: 0, }
}

///|
fn Scope::find_table(self : Scope, name : String) -> ScopeTable? {
  let f = fold_name(name)
  for t in self.tables {
    if fold_name(t.name) == f {
      return Some(t)
    }
  }
  None
}

///|
fn bind_column(
  scope : Scope,
  tq : String?,
  name : String,
  dq : Bool,
) -> BExpr raise SqlError {
  let f = fold_name(name)
  match tq {
    Some(t) => {
      guard scope.find_table(t) is Some(st) else {
        raise err("no such column: " + t + "." + name)
      }
      for i, c in st.columns {
        if fold_name(c.name) == f {
          return BCol(st.offset + i, c.affinity)
        }
      }
      raise err("no such column: " + t + "." + name)
    }
    None => {
      let mut found : BExpr? = None
      for st in scope.tables {
        for i, c in st.columns {
          if fold_name(c.name) == f {
            if found is Some(_) {
              raise err("ambiguous column name: " + name)
            }
            found = Some(BCol(st.offset + i, c.affinity))
          }
        }
      }
      match found {
        Some(b) => b
        None =>
          if dq {
            BConst(Text(name))
          } else {
            raise err("no such column: " + name)
          }
      }
    }
  }
}

///|
pub fn bind_expr(
  db : Database,
  scope : Scope,
  e : Expr,
) -> BExpr raise SqlError {
  ignore(db)
  match e {
    Lit(v) => BConst(v)
    Column(tq, name, dq) => bind_column(scope, tq, name, dq)
    Unary(op, x) => BUnary(op, bind_expr(db, scope, x))
    Binary(op, l, r) => {
      let bl = bind_expr(db, scope, l)
      let br = bind_expr(db, scope, r)
      match op {
        And => BAnd(bl, br)
        Or => BOr(bl, br)
        Eq | Ne | Lt | Le | Gt | Ge | Is | IsNot =>
          BCmp(op, bl, br, comparison_affinity(bl.affinity(), br.affinity()))
        _ => BArith(op, bl, br)
      }
    }
    IsNull(x, neg) => BIsNull(bind_expr(db, scope, x), neg)
    Between(x, lo, hi, neg) => {
      let bx = bind_expr(db, scope, x)
      let bl = bind_expr(db, scope, lo)
      let bh = bind_expr(db, scope, hi)
      let both = BAnd(
        BCmp(Ge, bx, bl, comparison_affinity(bx.affinity(), bl.affinity())),
        BCmp(Le, bx, bh, comparison_affinity(bx.affinity(), bh.affinity())),
      )
      if neg {
        BUnary(Not, both)
      } else {
        both
      }
    }
    InList(x, items, neg) => {
      let bx = bind_expr(db, scope, x)
      let bitems = items.map(i => bind_expr(db, scope, i))
      let aff = match bx.affinity() {
        Some(a) => a
        None => AffNone
      }
      BInList(bx, bitems, neg, aff)
    }
    Case(base, whens, els) =>
      BCase(
        base.map(b => bind_expr(db, scope, b)),
        whens.map(w => (bind_expr(db, scope, w.0), bind_expr(db, scope, w.1))),
        els.map(x => bind_expr(db, scope, x)),
      )
    Func(fc) => {
      if fc.star || fc.distinct || fc.over is Some(_) || fc.filter is Some(_) {
        raise err("unsupported use of function " + fc.name + "()")
      }
      let sf = lookup_scalar(fc.name, fc.args.length())
      BFunc(fc.name, sf.f, fc.args.map(a => bind_expr(db, scope, a)))
    }
    _ => raise err("unsupported expression")
  }
}

///|
/// Produces the scope and the flat rows for a FROM clause.
fn Database::from_rows(
  self : Database,
  from : FromItem?,
) -> (Scope, Array[Array[Value]]) raise SqlError {
  match from {
    None => (Scope::empty(), [[]])
