fn int_preserving(f : (Double) -> Double) -> ScalarFunc {
  {
    min_args: 1,
    max_args: 1,
    f: args => match args[0].numeric_strict() {
      Some(Int(i)) => Int(i)
      Some(v) => real_or_null(f(v.as_double()))
      None => Null
    },
  }
}

