///|
pub(all) enum UnOp {
  Neg
  Pos
  Not
  BitNot
} derive(Debug, Eq)

///|
pub(all) enum BinOp {
  Add
  Sub
  Mul
  Div
  Mod
  Concat
  Eq
  Ne
  Lt
  Le
  Gt
  Ge
  And
  Or
  BitAnd
  BitOr
  Shl
  Shr
  Is
  IsNot
} derive(Debug, Eq)

///|
pub(all) enum Expr {
  Lit(Value)
  /// Column reference: optional table qualifier, column name, and whether
  /// the name was a bare double-quoted token (may fall back to a string).
  Column(String?, String, Bool)
  Unary(UnOp, Expr)
  Binary(BinOp, Expr, Expr)
  /// IS NULL (false) / NOT NULL (true)
  IsNull(Expr, Bool)
  Between(Expr, Expr, Expr, Bool)
  InList(Expr, Array[Expr], Bool)
  InSelect(Expr, Select, Bool)
  /// op name ("LIKE", "GLOB", ...), lhs, pattern, escape, negated
  Like(String, Expr, Expr, Expr?, Bool)
  Case(Expr?, Array[(Expr, Expr)], Expr?)
  Cast(Expr, String)
  Collate(Expr, String)
  Func(FuncCall)
  Exists(Select, Bool)
  Subquery(Select)
  Param(String)
} derive(Debug)

///|
pub(all) struct FuncCall {
  name : String
  args : Array[Expr]
  distinct : Bool
  star : Bool
  filter : Expr?
  order_by : Array[OrderTerm]
  over : WindowSpec?
} derive(Debug)

///|
pub(all) struct WindowSpec {
  base : String?
  partition_by : Array[Expr]
  order_by : Array[OrderTerm]
  frame : FrameSpec?
} derive(Debug)

///|
pub(all) enum FrameBound {
  UnboundedPreceding
  Preceding(Expr)
  CurrentRow
  Following(Expr)
  UnboundedFollowing
} derive(Debug)

///|
pub(all) struct FrameSpec {
  unit : String // ROWS | RANGE | GROUPS
  start : FrameBound
  end : FrameBound
  exclude : String // NO OTHERS | CURRENT ROW | GROUP | TIES
} derive(Debug)

///|
pub(all) struct OrderTerm {
  expr : Expr
  desc : Bool
  nulls_first : Bool? // None = default
} derive(Debug)

///|
pub(all) enum ResultCol {
  Star
  TableStar(String)
  ExprCol(Expr, String?)
} derive(Debug)

///|
pub(all) enum JoinKind {
  Inner
  Left
  Right
  Full
  Cross
} derive(Debug, Eq)

///|
pub(all) enum FromItem {
  TableRef(String, String?)
  SubqueryRef(Select, String?)
  Join(FromItem, FromItem, JoinKind, Bool, Expr?, Array[String]?) // natural, on, using
} derive(Debug)

///|
pub(all) struct SimpleSelect {
  distinct : Bool
  columns : Array[ResultCol]
  from : FromItem?
  where_ : Expr?
  group_by : Array[Expr]
  having : Expr?
  windows : Array[(String, WindowSpec)]
} derive(Debug)

///|
pub(all) enum SelectCore {
  Simple(SimpleSelect)
  Values(Array[Array[Expr]])
} derive(Debug)

///|
pub(all) enum CompoundOp {
  Union
  UnionAll
  Intersect
  Except
} derive(Debug, Eq)

///|
pub(all) struct Cte {
  name : String
  columns : Array[String]
  select : Select
  materialized : Bool?
} derive(Debug)

///|
pub(all) struct Select {
  with_ : Array[Cte]
  recursive : Bool
  first : SelectCore
  rest : Array[(CompoundOp, SelectCore)]
  order_by : Array[OrderTerm]
  limit : Expr?
  offset : Expr?
} derive(Debug)

///|
pub(all) struct ColumnDef {
  name : String
  type_name : String
  mut primary_key : Bool
  mut pk_desc : Bool
  mut autoincrement : Bool
  mut not_null : Bool
  mut unique : Bool
  mut default : Expr?
  checks : Array[Expr]
  mut collate : String?
  mut pk_conflict : String?
  mut nn_conflict : String?
  mut unique_conflict : String?
} derive(Debug)

///|
pub(all) enum TableConstraint {
  PrimaryKey(Array[(String, String?, Bool)], String?) // (column, collate, desc), conflict
  Unique(Array[(String, String?, Bool)], String?)
  Check(Expr)
  ForeignKey(Array[String], String, Array[String])
} derive(Debug)

///|
pub(all) struct CreateTable {
  name : String
  if_not_exists : Bool
  columns : Array[ColumnDef]
  constraints : Array[TableConstraint]
} derive(Debug)

///|
pub(all) enum InsertSource {
  InsValues(Array[Array[Expr]])
  InsSelect(Select)
  InsDefault
} derive(Debug)

///|
pub(all) struct Insert {
  table : String
  columns : Array[String]?
  source : InsertSource
  or_action : String? // REPLACE, IGNORE, ABORT, FAIL, ROLLBACK
} derive(Debug)

///|
pub(all) enum Stmt {
  CreateTableStmt(CreateTable)
  DropTableStmt(String, Bool)
  InsertStmt(Insert)
  SelectStmt(Select)
} derive(Debug)
///|
pub(all) struct TableColumn {
  name : String
  type_name : String
  affinity : Affinity
  coll : Coll
  def : ColumnDef
}

///|
pub(all) struct Table {
  name : String
  columns : Array[TableColumn]
  constraints : Array[TableConstraint]
  rows : @sorted_map.SortedMap[Int64, Array[Value]]
  mut max_rowid : Int64
}

///|
pub(all) struct Database {
  tables : Map[String, Table]
}

///|
pub fn Database::new() -> Database {
  { tables: Map([]), }
}

///|
pub fn fold_name(s : String) -> String {
  s.to_lower()
}

///|
pub fn Database::find_table(self : Database, name : String) -> Table? {
  self.tables.get(fold_name(name))
}

///|
pub fn Database::get_table(
  self : Database,
  name : String,
) -> Table raise SqlError {
  match self.find_table(name) {
    Some(t) => t
    None => raise err("no such table: " + name)
  }
}

///|
pub fn Table::column_index(self : Table, name : String) -> Int? {
  let f = fold_name(name)
  for i, c in self.columns {
    if fold_name(c.name) == f {
      return Some(i)
    }
  }
  None
}

///|
pub fn Table::insert_row(self : Table, row : Array[Value]) -> Int64 {
  let id = self.max_rowid + 1L
  self.max_rowid = id
  self.rows.set(id, row)
  id
}

///|
/// Result of executing one statement.
pub(all) struct QueryResult {
  columns : Array[String]
  rows : Array[Array[Value]]
}

///|
pub fn Database::execute(
  self : Database,
  sql : String,
) -> QueryResult raise SqlError {
  let stmt = parse_statement(sql)
  match stmt {
    CreateTableStmt(ct) => {
      self.create_table(ct)
      { columns: [], rows: [], }
    }
    DropTableStmt(name, if_exists) => {
      match self.find_table(name) {
        Some(_) => self.tables.remove(fold_name(name))
        None => if !if_exists { raise err("no such table: " + name) }
      }
      { columns: [], rows: [], }
    }
    InsertStmt(ins) => {
      self.insert(ins)
      { columns: [], rows: [], }

///|
pub(all) struct ScopeTable {
  name : String
  columns : Array[TableColumn]
  offset : Int
}

///|
pub(all) struct Scope {
  tables : Array[ScopeTable]
  width : Int
}

///|
pub fn Scope::empty() -> Scope {
  { tables: [], width: 0, }
}

///|
fn Scope::find_table(self : Scope, name : String) -> ScopeTable? {
  let f = fold_name(name)
  for t in self.tables {
    if fold_name(t.name) == f {
      return Some(t)
    }
  }
  None
}

///|
fn bind_column(
  scope : Scope,
  tq : String?,
  name : String,
  dq : Bool,
) -> BExpr raise SqlError {
  let f = fold_name(name)
  match tq {
    Some(t) => {
      guard scope.find_table(t) is Some(st) else {
        raise err("no such column: " + t + "." + name)
      }
      for i, c in st.columns {
        if fold_name(c.name) == f {
          return BCol(st.offset + i, c.affinity, c.coll)
        }
      }
      raise err("no such column: " + t + "." + name)
    }
    None => {
      let mut found : BExpr? = None
      for st in scope.tables {
        for i, c in st.columns {
          if fold_name(c.name) == f {
            if found is Some(_) {
              raise err("ambiguous column name: " + name)
            }
            found = Some(BCol(st.offset + i, c.affinity, c.coll))
          }
        }
      }
      match found {
        Some(b) => b
        None =>
          if dq {
            BConst(Text(name))
          } else {
            raise err("no such column: " + name)
          }
      }
    }
  }
}

///|
fn bind_cmp(op : BinOp, l : BExpr, r : BExpr) -> BExpr raise SqlError {
  BCmp(
    op,
    l,
    r,
    comparison_affinity(l.affinity(), r.affinity()),
    binary_collation(l, r),
  )
}

///|
/// True if the expression references no columns or subqueries.
fn is_constant_expr(e : Expr) -> Bool {
  match e {
    Lit(_) | Param(_) => true
    Column(_, _, _) | InSelect(_, _, _) | Exists(_, _) | Subquery(_) => false
    Unary(_, x) | IsNull(x, _) | Cast(x, _) | Collate(x, _) =>
      is_constant_expr(x)
    Binary(_, l, r) => is_constant_expr(l) && is_constant_expr(r)
    Between(x, l, h, _) =>
      is_constant_expr(x) && is_constant_expr(l) && is_constant_expr(h)
    InList(x, items, _) => is_constant_expr(x) && items.all(is_constant_expr)
    Like(_, l, p, esc, _) =>
      is_constant_expr(l) &&
      is_constant_expr(p) &&
      (match esc {
        Some(x) => is_constant_expr(x)
        None => true
      })
    Case(b, whens, els) =>
      (match b {
        Some(x) => is_constant_expr(x)
        None => true
      }) &&
      whens.all(w => is_constant_expr(w.0) && is_constant_expr(w.1)) &&
      (match els {
        Some(x) => is_constant_expr(x)
        None => true
      })
    Func(fc) => fc.over is None && fc.args.all(is_constant_expr)
  }
}

///|
pub fn bind_expr(
  db : Database,
  scope : Scope,
  e : Expr,
) -> BExpr raise SqlError {
  match e {
    Lit(v) => BConst(v)
    Column(tq, name, dq) => bind_column(scope, tq, name, dq)
    Unary(op, x) => BUnary(op, bind_expr(db, scope, x))
    Binary(op, l, r) => {
      let bl = bind_expr(db, scope, l)
      let br = bind_expr(db, scope, r)
      match op {
        And => BAnd(bl, br)
        Or => BOr(bl, br)
        Eq | Ne | Lt | Le | Gt | Ge | Is | IsNot => bind_cmp(op, bl, br)
        _ => BArith(op, bl, br)
      }
    }
    IsNull(x, neg) => BIsNull(bind_expr(db, scope, x), neg)
    Between(x, lo, hi, neg) => {
      let bx = bind_expr(db, scope, x)
      let bl = bind_expr(db, scope, lo)
      let bh = bind_expr(db, scope, hi)
      let both = BAnd(bind_cmp(Ge, bx, bl), bind_cmp(Le, bx, bh))
      if neg {
        BUnary(Not, both)
      } else {
        both
      }
    }
    InList(x, items, neg) => {
      let bx = bind_expr(db, scope, x)
      let bitems = items.map(i => bind_expr(db, scope, i))
      // Like SQLite, `x IN (const)` is rewritten to `x = +const`.
      if items.length() == 1 && is_constant_expr(items[0]) {
        return bind_cmp(if neg { Ne } else { Eq }, bx, BUnary(Pos, bitems[0]))
      }
      let aff = match bx.affinity() {
        Some(a) => a
        None => AffNone
      }
      BInList(
        bx,
        bitems,
        neg,
        aff,
        check_coll(bx.collation().unwrap_or(CBinary)),
      )
    }
    Case(base, whens, els) => {
      let bbase = base.map(b => bind_expr(db, scope, b))
      let arms = whens.map(w => {
        let bw = bind_expr(db, scope, w.0)
        let bt = bind_expr(db, scope, w.1)
        match bbase {
          Some(b) =>
            (
              bw,
              bt,
              comparison_affinity(b.affinity(), bw.affinity()),
              binary_collation(b, bw),
            )
          None => (bw, bt, AffNone, CBinary)
        }
      })
      BCase(bbase, arms, els.map(x => bind_expr(db, scope, x)))
    }
    Cast(x, t) => BCast(bind_expr(db, scope, x), affinity_of_type(t))
    Collate(x, name) => BCollate(bind_expr(db, scope, x), coll_of_name(name))
    Like(op, lhs, pat, esc, neg) => {
      let fname = op.to_lower()
      let args = [pat, lhs]
      if esc is Some(x) {
        args.push(x)
      }
      let call = bind_function(db, scope, fname, args)
      if neg {
        BUnary(Not, call)
      } else {
        call
      }
    }
    Func(fc) => {
      if fc.star || fc.distinct || fc.over is Some(_) || fc.filter is Some(_) {
        raise err("unsupported use of function " + fc.name + "()")
      }
      bind_function(db, scope, fc.name, fc.args)
    }
    _ => raise err("unsupported expression")
  }
}

