        if constraints.length() > 0 {
          raise self.syntax_error()
        }
        columns.push(self.column_def())
      }
      if !self.eat_op(",") {
        break
      }
    }
    self.expect_op(")")
    // table options
    while self.is_kw("WITHOUT") || self.is_kw("STRICT") {
      if self.eat_kw("WITHOUT") {
        let _ = self.name()
      } else {
        self.pos += 1
      }
      if !self.eat_op(",") {
        break
      }
    }
    CreateTableStmt({ name, if_not_exists, columns, constraints, })
  } else {
    raise self.syntax_error()
  }
}

