fn Parser::or_clause(self : Parser) -> String? raise SqlError {
  if !self.eat_kw("OR") {
    return None
  }
  match self.advance() {
    Word(w) => {
      let u = w.to_upper()
      if u == "REPLACE" ||
        u == "IGNORE" ||
        u == "ABORT" ||
        u == "FAIL" ||
        u == "ROLLBACK" {
        Some(u)
      } else {
        self.pos -= 1
        raise self.syntax_error()
      }
    }
    _ => {
      self.pos -= 1
      raise self.syntax_error()
    }
  }
}

///|
fn Parser::set_list(self : Parser) -> Array[(String, Expr)] raise SqlError {
  let sets = []
  while true {
    if self.eat_op("(") {
      let names = [self.name()]
      while self.eat_op(",") {
        names.push(self.name())
      }
      self.expect_op(")")
      self.expect_op("=")
      self.expect_op("(")
      let vals = [self.expr()]
      while self.eat_op(",") {
        vals.push(self.expr())
      }
      self.expect_op(")")
      if vals.length() != names.length() {
        raise err(
          "\\{names.length()} columns assigned \\{vals.length()} values",
        )
      }
      for i, n in names {
        sets.push((n, vals[i]))
      }
    } else {
      let n = self.name()
      self.expect_op("=")
      sets.push((n, self.expr()))
    }
    if !self.eat_op(",") {
      break
    }
  }
  sets
}

