pub fn Table::current_max_rowid(self : Table) -> Int64 {
  if self.max_dirty {
    let mut m = 0L
    let mut first = true
    for k in self.rows.keys() {
      if first || k > m {
        m = k
        first = false
      }
    }
    self.max_rowid = m
    self.max_dirty = false
  }
  if self.rows.is_empty() {
    0L
  } else {
    self.max_rowid
  }
}

