///|
fn bind_column(
  scope : Scope,
  tq : String?,
  name : String,
  dq : Bool,
) -> BExpr raise SqlError {
  let f = fold_name(name)
  match tq {
    Some(t) => {
      guard scope.find_table(t) is Some(st) else {
        raise err("no such column: " + t + "." + name)
      }
      for i, c in st.columns {
        if fold_name(c.name) == f {
          return BCol(st.offset + i, c.affinity, c.coll)
        }
      }
      if is_rowid_name(f) && st.rowid_slot >= 0 {
        return BCol(st.rowid_slot, AffInteger, CBinary)
      }
      raise err("no such column: " + t + "." + name)
    }
    None => {
      let mut found : BExpr? = None
      for st in scope.tables {
        if st.qualified_only {
          continue
        }
        for i, c in st.columns {
          if fold_name(c.name) == f {
            if found is Some(_) {
              raise err("ambiguous column name: " + name)
            }
            found = Some(BCol(st.offset + i, c.affinity, c.coll))
          }
        }
      }
      if found is None && is_rowid_name(f) {
        for st in scope.tables {
          if st.qualified_only {
            continue
          }
          if st.rowid_slot >= 0 {
            if found is Some(_) {
              raise err("ambiguous column name: " + name)
            }
            found = Some(BCol(st.rowid_slot, AffInteger, CBinary))
          }
