/// True if the expression contains a subquery.
fn has_subquery(e : Expr) -> Bool {
  let mut found = false
  walk_expr(e, x => if x is (Subquery(_) | Exists(_, _) | InSelect(_, _, _)) {
    found = true
  })
  found
}

///|
/// Calls `f` on every expression node (not descending into subqueries).
fn walk_expr(e : Expr, f : (Expr) -> Unit) -> Unit {
  f(e)
  match e {
    Lit(_) | Column(_, _, _) | Param(_) | AggSlot(_) => ()
    Subquery(_) | Exists(_, _) => ()
    InSelect(x, _, _) => walk_expr(x, f)
    Unary(_, x) | IsNull(x, _) | Cast(x, _) | Collate(x, _) => walk_expr(x, f)
    Binary(_, l, r) => {
      walk_expr(l, f)
      walk_expr(r, f)
    }
    Between(x, l, h, _) => {
      walk_expr(x, f)
      walk_expr(l, f)
      walk_expr(h, f)
    }
    InList(x, items, _) => {
      walk_expr(x, f)
      for i in items {
        walk_expr(i, f)
      }
    }
    Like(_, l, p, esc, _) => {
      walk_expr(l, f)
      walk_expr(p, f)
      if esc is Some(x) {
        walk_expr(x, f)
      }
    }
    Case(b, whens, els) => {
      if b is Some(x) {
        walk_expr(x, f)
      }
      for w in whens {
        walk_expr(w.0, f)
        walk_expr(w.1, f)
      }
      if els is Some(x) {
        walk_expr(x, f)
      }
    }
    Func(fc) => {
      for a in fc.args {
        walk_expr(a, f)
      }
      if fc.filter is Some(x) {
        walk_expr(x, f)
      }
    }
  }
}

