fn choose_index_plan(
  t : Table,
  filters : Array[BExpr],
  off : Int,
  probe_limit? : (Int, Int) = (0, 0),
) -> IndexPlan? {
  if filters.length() == 0 {
    return None
  }
  let ncols = t.columns.length()
  let mut best : IndexPlan? = None
  let consider = (p : IndexPlan?) => {
    if p is Some(x) {
      match best {
        Some(b) if b.score >= x.score => ()
        _ => best = Some(x)
      }
    }
  }
  let rowid_key = BCol(ncols, AffInteger, CBinary)
  match plan_keys(None, [rowid_key], [CBinary], filters, off, true, probe_limit) {
    Some(p) => consider(Some({ ..p, score: p.score + 100 }))
    None => ()
  }
  if t.ipk >= 0 {
    let k = BCol(t.ipk, AffInteger, t.columns[t.ipk].coll)
    match plan_keys(None, [k], [t.columns[t.ipk].coll], filters, off, true, probe_limit) {
      Some(p) => consider(Some({ ..p, score: p.score + 100 }))
      None => ()
    }
  }
  for idx in t.indexes {
    if idx.pred is Some(p) && !implies_predicate(p, filters, off) {
      continue
    }
    consider(
      plan_keys(
        Some(idx),
        idx.keys,
        idx.colls,
        filters,
        off,
        idx.unique,
        probe_limit,
      ),
    )
  }
  best
}

