///|
/// Estimated rows produced by an index plan (LogEst).
fn plan_nout(p : IndexPlan) -> Int {
  let k = p.eqs.length()
  let mut nout = match p.index {
    None => if k > 0 { 0 } else { default_rows }
    Some(idx) =>
      if k == 0 {
        if idx.pred is Some(_) {
          default_rows - 10
        } else {
          default_rows
        }
      } else if idx.unique && k == idx.keys.length() {
        0
      } else {
        [33, 32, 30, 28, 26].get(k - 1).unwrap_or(23)
      }
  }
  for alts in p.eqs {
    if alts.length() > 1 {
      nout += log_est(alts.length())
    }
  }
  let nb = (if p.lo is Some(_) { 1 } else { 0 }) +
    (if p.hi is Some(_) { 1 } else { 0 })
  nout -= 20 * nb
  if nb == 2 {
    nout -= 20
  }
  nout
}
