) -> (IndexPlan?, Bool, Bool) {
  let ncols = t.columns.length()
  let tw = table_row_width(t)
  let mut best : (IndexPlan?, Bool, Bool) = (None, false, false)
  let mut best_cost = @int.MAX_VALUE
  let mut best_nout = @int.MAX_VALUE
  let consider = (p : IndexPlan?, run_cost : Int, nout0 : Int) => {
    let nrow = match p {
      Some({ index: Some(idx), .. }) if idx.pred is Some(_) => default_rows - 10
      _ => default_rows
    }
    let consumed = match p {
      Some(x) => x.consumed.length()
      None => 0
    }
    // Output estimate after the terms the plan does not enforce.
    let mut nout = nout0 - (filters.length() - consumed)
    let mut reduce = 0
    for fi, f in filters {
      if p is Some(x) && x.consumed.contains(fi) {
        continue
      }
      if f is BCmp(Eq | Is, _, _, _, _) {
        reduce = 20
      }
    }
    if nout > nrow - reduce {
      nout = nrow - reduce
    }
    let mut total = run_cost
    let mut satisfied = false
    let mut rev = false
    if hint is Some(h) {
      let (index, eqs) = match p {
        Some(x) => (x.index, x.eqs)
        None => (None, [])
      }
      let single = eqs.map(a => a.length() == 1)
      let (nsat, r) = order_satisfied(t, index, single, eqs.length(), h, filters, off)
      let nterms = h.terms.length()
      if nsat >= nterms {
        satisfied = true
        rev = r
      } else {
        let mut sort = nout + log_est((h.ncols + 59) / 30)
        if nsat > 0 {
          sort += log_est((nterms - nsat) * 100 / nterms) - 66
        }
        if h.has_limit {
          sort += 10
        }
        sort += est_log(nout)
        total = log_est_add(run_cost, sort) + 3
      }
    }
    // Ties go to the plan producing fewer rows.
    if total < best_cost || (total == best_cost && nout < best_nout) {
      best = (p, rev, satisfied)
      best_cost = total
      best_nout = nout
    }
  }
  // Full table scan.
  consider(None, default_rows + 16, default_rows)
  if filters.length() > 0 {
    let rowid_key = BCol(ncols, AffInteger, CBinary)
