      }
      None => ()
    }
    // Full scan of the index.
    let w = index_row_width(t, idx)
    let covering = index_covers(t, idx, used)
    let helps = match hint {
      Some(h) =>
        h.terms.any(term => {
          idx.keys.any(k => bexpr_same(k, term.0, off)) ||
          (term.0 is BCol(c, _, _) &&
          (c == off + ncols || (t.ipk >= 0 && c == off + t.ipk)))
        })
      None => false
    }
