fn[K : Compare, V] upper_bound(c : Array[(K, V)], k : K) -> Int {
  let mut lo = 0
  let mut hi = c.length()
  while lo < hi {
    let mid = (lo + hi) / 2
    if c[mid].0.compare(k) <= 0 {
      lo = mid + 1
    } else {
      hi = mid
    }
  }
