fn plan_keys(
  index : Index?,
  keys : Array[BExpr],
  colls : Array[Coll],
  filters : Array[BExpr],
  off : Int,
  limit : (Int, Int),
) -> IndexPlan? {
  let eqs = []
  let consumed = []
  let mut lo = None
  let mut hi = None
  let mut lo_term = -1
  let mut hi_term = -1
  for j, key in keys {
    let ka = key.affinity()
    let mut eq : Array[(BExpr, Affinity, Bool)]? = None
    let mut eq_term = -1
    lo = None
    hi = None
    for fi, f in filters {
      match term_constraint(f, key, off, colls[j], ka, limit) {
        Some(CEq(alts)) =>
          match eq {
            Some(prev) if prev.length() == 1 => ()
            _ => {
              eq = Some(alts)
              eq_term = fi
            }
          }
        Some(CLo(e, a, inc)) =>
          if lo is None {
            lo = Some((e, a, inc))
            lo_term = fi
          }
        Some(CHi(e, a, inc)) =>
          if hi is None {
            hi = Some((e, a, inc))
            hi_term = fi
          }
        None => ()
      }
    }
    match eq {
      Some(alts) => {
        eqs.push(alts)
        consumed.push(eq_term)
      }
      None => break
    }
  }
  if eqs.length() == keys.length() {
    lo = None
    hi = None
  }
  if lo is Some(_) {
    consumed.push(lo_term)
  }
  if hi is Some(_) {
    consumed.push(hi_term)
  }
  if eqs.length() == 0 && lo is None && hi is None {
    return None
  }
  Some({ index, eqs, lo, hi, consumed, })
}

