///|
fn Parser::window_spec(self : Parser) -> WindowSpec raise SqlError {
  self.expect_op("(")
  let mut base : String? = None
  match self.peek() {
    Word(w) if !reserved_words.contains(w.to_upper()) &&
      !(w.to_upper() == "ROWS" ||
      w.to_upper() == "RANGE" ||
      w.to_upper() == "GROUPS") => {
      self.pos += 1
      base = Some(w)
    }
    _ => ()
  }
  let partition_by = []
  if self.eat_kw("PARTITION") {
    self.expect_kw("BY")
    partition_by.push(self.expr())
    while self.eat_op(",") {
      partition_by.push(self.expr())
    }
  }
  let order_by = if self.is_kw("ORDER") {
    self.pos += 1
    self.expect_kw("BY")
    self.order_terms()
  } else {
    []
  }
  let mut frame : FrameSpec? = None
  if self.is_kw("ROWS") || self.is_kw("RANGE") || self.is_kw("GROUPS") {
    let unit = match self.advance() {
      Word(w) => w.to_upper()
      _ => ""
    }
    let (start, end) = if self.eat_kw("BETWEEN") {
      let s = self.frame_bound()
      self.expect_kw("AND")
      let e = self.frame_bound()
      (s, e)
    } else {
      (self.frame_bound(), CurrentRow)
    }
    let mut exclude = "NO OTHERS"
    if self.eat_kw("EXCLUDE") {
      if self.eat_kw("NO") {
        self.expect_kw("OTHERS")
      } else if self.eat_kw("CURRENT") {
        self.expect_kw("ROW")
        exclude = "CURRENT ROW"
      } else if self.eat_kw("GROUP") {
        exclude = "GROUP"
      } else {
        self.expect_kw("TIES")
        exclude = "TIES"
      }
    }
    frame = Some({ unit, start, end, exclude, })
  }
  self.expect_op(")")
  { base, partition_by, order_by, frame, }
}

///|
fn Parser::frame_bound(self : Parser) -> FrameBound raise SqlError {
  if self.eat_kw("UNBOUNDED") {
    if self.eat_kw("PRECEDING") {
      UnboundedPreceding
    } else {
      self.expect_kw("FOLLOWING")
      UnboundedFollowing
    }
  } else if self.eat_kw("CURRENT") {
    self.expect_kw("ROW")
    CurrentRow
  } else {
    let e = self.expr()
    if self.eat_kw("PRECEDING") {
      Preceding(e)
    } else {
      self.expect_kw("FOLLOWING")
      Following(e)
    args.push(self.expr())
    while self.eat_op(",") {
      args.push(self.expr())
    }
    if self.is_kw("ORDER") {
      self.pos += 1
      self.expect_kw("BY")
      order_by = self.order_terms()
    }
  }
  self.expect_op(")")
  let mut filter : Expr? = None
  if self.eat_kw("FILTER") {
    self.expect_op("(")
    self.expect_kw("WHERE")
    filter = Some(self.expr())
    self.expect_op(")")
  }
  let mut over : WindowSpec? = None
  if self.eat_kw("OVER") {
    if self.is_op("(") {
      over = Some(self.window_spec())
    } else {
      let n = self.name()
      over = Some({
        base: Some(n),
        partition_by: [],
        order_by: [],
        frame: None,
      })
    }
  }
  Func({ name, args, distinct, star, filter, order_by, over, })
}

///|
/// Bumped on every row change in any table.
let data_version : Ref[Int] = { val: 0, }

///|
fn Table::raw_put(self : Table, rowid : Int64, row : Array[Value]) -> Unit {
  self.version += 1
  data_version.val += 1
  self.rows.set(rowid, row)
  if self.rows.length() == 1 || rowid > self.max_rowid {
    self.max_rowid = rowid
  }
  if self.indexes.length() > 0 {
    let full = full_row(row, rowid)
    for idx in self.indexes {
      idx.add_row(full, rowid, row)
    }
  }
}

///|
fn Table::raw_remove(self : Table, rowid : Int64) -> Array[Value]? {
  guard self.rows.get(rowid) is Some(row) else { return None }
  self.version += 1
  data_version.val += 1
  self.rows.remove(rowid)
  if self.indexes.length() > 0 {
    let full = full_row(row, rowid)
    for idx in self.indexes {
      idx.remove_row(full, rowid)
}

///|
pub fn Database::execute(
  self : Database,
  sql : String,
) -> QueryResult raise SqlError {
  let stmt = parse_statement(sql)
  self.cur_sql = sql
  let mark = self.undo.length()
  self.stmt_changes = 0L
  self.fail_keep = false
  self.in_dml = false
  self.rollback_txn = false
  outer_rows.clear()
  self.expanding.clear()
  let res = self.execute_stmt(stmt) catch {
    e => {
      if self.rollback_txn {
        self.rollback_to(0)
        self.end_txn()
        self.changes = 0L
      } else if self.in_dml {
        if self.fail_keep {
          self.changes = self.stmt_changes
          self.total_changes += self.stmt_changes
        } else {
          self.rollback_to(mark)
          self.changes = 0L
        }
      } else {
        self.rollback_to(mark)
      }
      if !self.in_txn {
        self.undo.clear()
      }
      raise e
    }
  }
  if self.in_dml {
    self.changes = self.stmt_changes
    self.total_changes += self.stmt_changes
  }
  if !self.in_txn {
    self.undo.clear()
  }
  res
}

///|
fn Database::execute_stmt(
  self : Database,
  stmt : Stmt,
) -> QueryResult raise SqlError {
  match stmt {
    CreateTableStmt(ct) => self.create_table(ct)
    DropTableStmt(name, if_exists) => self.drop_table(name, if_exists)
    CreateIndexStmt(ci) => self.create_index(ci)
    DropIndexStmt(name, if_exists) => self.drop_index(name, if_exists)
    CreateViewStmt(cv) => self.create_view(cv)
    DropViewStmt(name, if_exists) => self.drop_view(name, if_exists)
    AlterStmt(name, action) => self.alter_table(name, action)
    BeginStmt => {
      if self.in_txn {
        raise err("cannot start a transaction within a transaction")
      }
      self.undo.clear()
      self.in_txn = true
      self.txn_by_savepoint = false
    }
    CommitStmt => {
      if !self.in_txn {
        raise err("cannot commit - no transaction is active")
      }
      self.end_txn()
    }
    RollbackStmt(None) => {
      if !self.in_txn {
        raise err("cannot rollback - no transaction is active")
      }
      self.rollback_to(0)
      self.end_txn()
    }
    RollbackStmt(Some(name)) => {
      let i = self.find_savepoint(name)
      self.rollback_to(self.savepoints[i].1)
      self.savepoints.truncate(i + 1)
    }
    SavepointStmt(name) => {
      if !self.in_txn {
        self.undo.clear()
        self.in_txn = true
        self.txn_by_savepoint = true
      }
      self.savepoints.push((name, self.undo.length()))
    }
    ReleaseStmt(name) => {
      let i = self.find_savepoint(name)
      self.savepoints.truncate(i)
      if self.savepoints.length() == 0 && self.txn_by_savepoint {
        self.end_txn()
      }
