pub struct Parser<'a> {
    src: &'a str,
    toks: Vec<Token>,
    pos: usize,
}

pub fn parse_statement(src: &str) -> Result<Stmt> {
    let toks = tokenize(src)?;
    let mut p = Parser { src, toks, pos: 0 };
    let stmt = p.statement()?;
    while p.eat_op(";") {}
    if !p.at_eof() {
        return Err(p.syntax_error());
    }
    Ok(stmt)
}

