use std::collections::BTreeMap;

use crate::ast::{Conflict, Expr};
use crate::value::{Affinity, Value};

#[derive(Clone, Debug)]
pub struct Column {
    pub name: String,
    pub decl_type: String,
    pub affinity: Affinity,
    pub not_null: Option<Conflict>,
    pub default: Option<Expr>,
    pub collation: Option<String>,
}

#[derive(Clone, Debug)]
pub struct UniqueKey {
    pub cols: Vec<usize>,
    pub conflict: Option<Conflict>,
    pub primary: bool,
}

#[derive(Clone, Debug)]
pub struct Table {
    pub name: String,
    pub columns: Vec<Column>,
    /// Rows keyed by rowid; each row has one value per column.
    pub rows: BTreeMap<i64, Vec<Value>>,
    /// Column that aliases the rowid (INTEGER PRIMARY KEY).
    pub rowid_alias: Option<usize>,
    pub autoincrement: bool,
    pub uniques: Vec<UniqueKey>,
    pub checks: Vec<Expr>,
    pub sql: String,
}

impl Table {
    pub fn column_index(&self, name: &str) -> Option<usize> {
        self.columns.iter().position(|c| c.name.eq_ignore_ascii_case(name))
    }

    pub fn next_rowid(&self) -> i64 {
        match self.rows.keys().next_back() {
            Some(&k) if k < i64::MAX => k + 1,
            Some(_) => {
                // Find an unused rowid.
                let mut r = 1;
                while self.rows.contains_key(&r) {
                    r += 1;
                }
                r
            }
            None => 1,
        }
    }
}

pub fn is_rowid_name(name: &str) -> bool {
    name.eq_ignore_ascii_case("rowid") || name.eq_ignore_ascii_case("oid") || name.eq_ignore_ascii_case("_rowid_")
}

#[derive(Clone, Debug, Default)]
pub struct Database {
    /// Keyed by ASCII-lowercased name.
    pub tables: BTreeMap<String, Table>,
}

pub fn key(name: &str) -> String {
    name.to_ascii_lowercase()
}

impl Database {
    pub fn table(&self, name: &str) -> Option<&Table> {
        self.tables.get(&key(name))
    }

    pub fn table_mut(&mut self, name: &str) -> Option<&mut Table> {
        self.tables.get_mut(&key(name))
    }
}
"}

