/// A FROM-clause source visible to name resolution.
#[derive(Clone, Debug)]
pub struct Source {
    /// Alias, or table name if no alias.
    pub name: String,
    pub columns: Vec<(String, Affinity)>,
    /// Index of this source's first column in the row.
    pub offset: usize,
    /// Index of the rowid in the row, if the source has one.
    pub rowid: Option<usize>,
}

#[derive(Clone, Debug, Default)]
pub struct Scope {
    pub sources: Vec<Source>,
}

impl Scope {
    fn resolve(&self, table: Option<&str>, name: &str) -> Result<Option<Expr>> {
        let mut found: Option<Expr> = None;
        for s in &self.sources {
            if let Some(t) = table {
                if !s.name.eq_ignore_ascii_case(t) {
                    continue;
                }
            }
            let hit = match s.columns.iter().position(|(c, _)| c.eq_ignore_ascii_case(name)) {
                Some(i) => Some(Expr::Col { idx: s.offset + i, aff: s.columns[i].1 }),
                None => match s.rowid {
                    Some(r) if is_rowid_name(name) => Some(Expr::Col { idx: r, aff: Affinity::Integer }),
                    _ => None,
                },
            };
            if let Some(h) = hit {
                if found.is_some() {
                    return err!("ambiguous column name: {}", name);
                }
                found = Some(h);
            }
        }
        Ok(found)
    }
}

/// Resolve column references in `e` against `scope`.
pub fn bind(e: &Expr, scope: &Scope) -> Result<Expr> {
    Ok(match e {
        Expr::Column { table, name, dq } => match scope.resolve(table.as_deref(), name)? {
            Some(c) => c,
            None => {
                if *dq && table.is_none() {
                    Expr::Lit(Value::Text(name.clone()))
                } else if let Some(t) = table {
                    return err!("no such column: {}.{}", t, name);
                } else {
                    return err!("no such column: {}", name);
                }
            }
        },
        Expr::Lit(_) | Expr::Col { .. } => e.clone(),
        Expr::Unary(op, a) => Expr::Unary(*op, Box::new(bind(a, scope)?)),
        Expr::Binary(op, a, b) => Expr::Binary(*op, Box::new(bind(a, scope)?), Box::new(bind(b, scope)?)),
        Expr::IsNull(a, neg) => Expr::IsNull(Box::new(bind(a, scope)?), *neg),
        Expr::Collate(a, c) => Expr::Collate(Box::new(bind(a, scope)?), c.clone()),
        Expr::Func { name, args, star, distinct } => {
            check_function(name, args.len(), *star)?;
            let args = args.iter().map(|a| bind(a, scope)).collect::<Result<Vec<_>>>()?;
            Expr::Func { name: name.clone(), args, star: *star, distinct: *distinct }
        }
    })
}

fn check_function(name: &str, nargs: usize, star: bool) -> Result<()> {
    let arity: &[usize] = match name {
