                has_content = true;
                let mut j = i + 1;
                while j < n {
                    if b[j] == c {
                        if j + 1 < n && b[j + 1] == c {
                            j += 2;
                            continue;
                        }
                        break;
                    }
                    j += 1;
                }
                i = (j + 1).min(n);
            }
            b'[' => {
                has_content = true;
                let mut j = i + 1;
                while j < n && b[j] != b']' {
                    j += 1;
                }
                i = (j + 1).min(n);
            }
            b'-' if i + 1 < n && b[i + 1] == b'-' => {
                while i < n && b[i] != b'\n' {
                    i += 1;
                }
            }
            b'/' if i + 1 < n && b[i + 1] == b'*' => {
                let mut j = i + 2;
