                    j += 1;
                }
                i = (j + 2).min(n);
            }
            b';' => {
                if has_content {
                    out.push(&script[start..i]);
                }
                has_content = false;
                i += 1;
                start = i;
            }
            _ => {
                if !c.is_ascii_whitespace() {
                    has_content = true;
                }
                i += 1;
            }
        }
    }
    if has_content {
        out.push(&script[start..]);
    }
    out
}

fn main() {
    let input = io::read_stdin();
    let mut engine = exec::Engine::new();
    for stmt in split_statements(&input) {
        match engine.execute(stmt) {
            Ok(rows) => {
                let mut s = String::new();
                for row in rows {
                    for (i, v) in row.iter().enumerate() {
                        if i > 0 {
                            s.push('|');
                        }
                        s.push_str(&v.render());
                    }
                    s.push('\n');
                }
                io::write_stdout(&s);
            }
            Err(e) => {
                io::write_stdout(&format!("Error: {}\n", e));
            }
        }
    }
    io::flush_stdout();
}
