14	/// Split a script into statements on `;` outside quotes and comments
15	/// (SPEC §2.2). Pieces holding only whitespace and comments are dropped.
16	fn split_statements(script: &str) -> Vec<&str> {
17	    let b = script.as_bytes();
18	    let n = b.len();
19	    let mut out = Vec::new();
20	    let mut start = 0;
21	    let mut has_content = false;
22	    let mut i = 0;
23	    while i < n {
24	        let c = b[i];
25	        match c {
26	            b'\'' | b'"' | b'`' => {
27	                has_content = true;
28	                let mut j = i + 1;
29	                while j < n {
30	                    if b[j] == c {
31	                        if j + 1 < n && b[j + 1] == c {
32	                            j += 2;
33	                            continue;
34	                        }
35	                        break;
36	                    }
37	                    j += 1;
38	                }
39	                i = (j + 1).min(n);
40	            }
41	            b'[' => {
42	                has_content = true;
43	                let mut j = i + 1;
44	                while j < n && b[j] != b']' {
45	                    j += 1;
46	                }
47	                i = (j + 1).min(n);
48	            }
49	            b'-' if i + 1 < n && b[i + 1] == b'-' => {
50	                while i < n && b[i] != b'\n' {
51	                    i += 1;
52	                }
53	            }
54	            b'/' if i + 1 < n && b[i + 1] == b'*' => {
55	                let mut j = i + 2;
56	                while j + 1 < n && !(b[j] == b'*' && b[j + 1] == b'/') {
57	                    j += 1;
58	                }
59	                i = (j + 2).min(n);
60	            }
61	            b';' => {
62	                if has_content {
63	                    out.push(&script[start..i]);
64	                }
65	                has_content = false;
66	                i += 1;
67	                start = i;
68	            }
69	            _ => {
70	                if !c.is_ascii_whitespace() {
71	                    has_content = true;
72	                }
73	                i += 1;
74	            }
75	        }
76	    }
77	    if has_content {
78	        out.push(&script[start..]);
79	    }
80	    out
81	}
