fn insert(&mut self, ins: &Insert) -> Result<Vec<Row>> {
    let tkey = key(&ins.table);
    let table = match self.db.tables.get(&tkey) {
        Some(t) => t,
        None => return err!("no such table: {}", ins.table),
    };
    let ncols = table.columns.len();
