fn at_eof(&self) -> bool {
    matches!(self.peek(), Tok::Eof)
}

fn syntax_error(&self) -> Error {
    let t = &self.toks[self.pos];
    if matches!(t.tok, Tok::Eof) {
        Error::new("incomplete input")
    } else {
        Error::new(format!("near \"{}\": syntax error", &self.src[t.pos..t.end]))
    }
}

