fn get_digits(z: &[u8], fields: &[(usize, i32, i32, u8)], out: &mut [i32]) -> usize {
    let mut p = 0;
    for (cnt, &(n, min, max, sep)) in fields.iter().enumerate() {
        let mut val = 0i32;
        for _ in 0..n {
            match z.get(p) {
                Some(c) if c.is_ascii_digit() => {
                    val = val * 10 + (c - b'0') as i32;
                    p += 1;
