                    buf[offset + n] = Value::Int(*rowid);
                    f(i, buf)?;
                }
            }
            Right::Rows(rows) => {
                for (i, r) in rows.iter().enumerate() {
                    buf[offset..offset + r.len()].clone_from_slice(r);
                    f(i, buf)?;
                }
            }
        }
        Ok(())
