        }
        if !right_matched.is_empty() {
            let mut buf: Row = vec![Value::Null; width];
            right.for_each(&mut buf, j.offset, &mut |ri, c| {
                if !right_matched[ri] && (!is_last || pass(c)?) {
                    out.push(c.to_vec());
                }
                Ok(())
            })?;
        }
        rows = out;
    }
    Ok(rows)
}

