fn conflict_action(&mut self) -> Result<Conflict> {
    let c = if self.eat_kw("ROLLBACK") {
        Conflict::Rollback
    } else if self.eat_kw("ABORT") {
        Conflict::Abort
    } else if self.eat_kw("FAIL") {
