        coll: Collation,
        /// Aggregate `FILTER (WHERE ...)`.
        filter: Option<Box<Expr>>,
        /// Aggregate `ORDER BY` inside the argument list.
        order_by: Vec<OrderTerm>,
    },
    /// Result of aggregate number `idx - base` in a post-aggregation row
    /// (read from `row[idx]`), with the aggregate's collation.
    AggRef {
        idx: usize,
        coll: Option<Collation>,
    },
    Cast(Box<Expr>, Affinity),
    Case {
        base: Option<Box<Expr>>,
        whens: Vec<(Expr, Expr)>,
        else_: Option<Box<Expr>>,
        /// Per-WHEN comparison info for the simple form (bound).
        infos: Vec<CmpInfo>,
    },
    Between {
        e: Box<Expr>,
        lo: Box<Expr>,
        hi: Box<Expr>,
        neg: bool,
        info_lo: CmpInfo,
        info_hi: CmpInfo,
    },
    InList {
        e: Box<Expr>,
        list: Vec<Expr>,
        neg: bool,
        info: CmpInfo,
    },
    Like {
        e: Box<Expr>,
        pat: Box<Expr>,
        esc: Option<Box<Expr>>,
        neg: bool,
        glob: bool,
