    Subquery(Box<Select>),
    /// Unbound `EXISTS (SELECT ...)`.
    Exists(Box<Select>),
    /// Unbound `e [NOT] IN (SELECT ...)`.
    InSelect { e: Box<Expr>, query: Box<Select>, neg: bool },
    /// Bound reference into the row of an enclosing query `up` levels out;
