}

fn create_view(&mut self) -> Result<Stmt> {
    let if_not_exists = self.if_not_exists()?;
    let name = self.qualified_name()?;
    let mut cols = None;
    if self.eat_op("(") {
        let mut v = Vec::new();
        loop {
            v.push(self.name()?);
            if !self.eat_op(",") {
