/// One entry of the undo log.
#[derive(Clone, Debug)]
pub enum Undo {
    /// The row at `rowid` of table `table` was `old` before the change.
    Row { table: String, rowid: i64, old: Option<Row> },
    /// The AUTOINCREMENT counter of `table` was `old`.
    Seq { table: String, old: i64 },
