                            return err!("AUTOINCREMENT is only allowed on an INTEGER PRIMARY KEY");
                        } else {
                            add_key(vec![(i, None)], *conflict, true, &mut indexes);
                        }
                    }
                    ColumnConstraint::Unique { conflict } => add_key(vec![(i, None)], *conflict, false, &mut indexes),
