    fn table_rows(&self, root: u32) -> Result<Vec<(i64, Vec<u8>)>> {
        let mut out = Vec::new();
        let max_local = self.usable - 35;
        let mut stack = vec![root];
        let mut visited = 0usize;
        let limit = self.data.len() / self.page_size + 1;
