            Stmt::Alter { table, action } => self.run_ddl(|e| e.alter(&table, action)),
            Stmt::Insert(ins) => self.run_dml(|e| e.insert(&ins)),
            Stmt::Update(upd) => self.run_dml(|e| e.update(&upd)),
