                false
            }
            None => {
                for scope in scopes.iter().rev() {
                    for s in scope {
                        let has = match &s.cols {
                            Some(c) => c.iter().any(|c| c.eq_ignore_ascii_case(name)),
                            None => false,
                        };
                        if has {
                            return s.is_target && name.eq_ignore_ascii_case(&self.col);
                        }
