#[derive(Debug, Clone)]
pub enum BExpr {
    Lit(Value),
    Col(usize, Affinity),
    Unary(UnOp, Box<BExpr>),
    Binary(BinOp, Box<BExpr>, Box<BExpr>),
    /// Comparison with the affinity to apply to its operands.
    Cmp(BinOp, Box<BExpr>, Box<BExpr>, Affinity),
    IsNull(Box<BExpr>),
    NotNull(Box<BExpr>),
    Between { expr: Box<BExpr>, lo: Box<BExpr>, hi: Box<BExpr>, not: bool, aff_lo: Affinity, aff_hi: Affinity },
    InList { expr: Box<BExpr>, list: Vec<BExpr>, not: bool, affs: Vec<Affinity> },
