}

fn expr_affinity(e: &BExpr) -> Affinity {
    match e {
        BExpr::Col(_, a) => *a,
        BExpr::Cast(_, a) => *a,
        BExpr::Collate(inner) => expr_affinity(inner),
        _ => Affinity::None,
    }
}

fn comparison_affinity(a: Affinity, b: Affinity) -> Affinity {
    if a > Affinity::None && b > Affinity::None {
        if a.is_numeric() || b.is_numeric() {
            Affinity::Numeric
        } else {
            Affinity::Blob
        }
    } else if a == Affinity::None {
        b
    } else {
        a
    }
}

struct Source {
    name: String,
    columns: Vec<String>,
    affinities: Vec<Affinity>,
    offset: usize,
}

#[derive(Default)]
struct Scope {
    sources: Vec<Source>,
}

impl Scope {
    fn resolve(&self, table: Option<&str>, name: &str) -> Result<Option<(usize, Affinity)>, String> {
        let lname = fold(name);
        let mut found = None;
        for s in &self.sources {
            if let Some(t) = table {
                if fold(t) != s.name {
                    continue;
                }
            }
            for (i, c) in s.columns.iter().enumerate() {
                if fold(c) == lname {
                    if found.is_some() {
                        return Err(format!("ambiguous column name: {}", name));
                    }
                    found = Some((s.offset + i, s.affinities[i]));
                }
            }
        }
        Ok(found)
    }
}

