fn resolve(&self, table: Option<&str>, name: &str) -> Result<Option<BExpr>, String> {
    let lname = fold(name);
    let mut found = None;
    for s in &self.sources {
        if let Some(t) = table {
            if fold(t) != s.name {
                continue;
            }
        }
        for (i, c) in s.columns.iter().enumerate() {
            if fold(c) == lname {
                if found.is_some() {
                    return Err(format!("ambiguous column name: {}", name));
                }
                found = Some(BExpr::Col(s.offset + i, s.affinities[i], s.colls[i]));
            }
        }
    }
    if found.is_none() && is_rowid_name(name) {
        for s in &self.sources {
            if let Some(t) = table {
                if fold(t) != s.name {
                    continue;
                }
            }
            if let Some(r) = s.rowid {
                if found.is_some() {
                    return Err(format!("ambiguous column name: {}", name));
                }
                found = Some(BExpr::Col(r, Affinity::Integer, Coll::Binary));
            }
        }
    }
    if found.is_none() && table.is_none() {
        if let Some((_, e)) = self.aliases.iter().find(|(a, _)| fold(a) == lname) {
            found = Some(e.clone());
        }
    }
    Ok(found)
}

