// Abstract syntax tree.

use crate::value::Value;

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum UnOp {
    Neg,
    Pos,
    Not,
    BitNot,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum BinOp {
    Add,
    Sub,
    Mul,
    Div,
    Rem,
    Concat,
    Eq,
    Ne,
    Lt,
    Le,
    Gt,
    Ge,
    Is,
    IsNot,
    And,
    Or,
    BitAnd,
    BitOr,
    Shl,
    Shr,
}

impl BinOp {
    pub fn is_comparison(self) -> bool {
        matches!(
            self,
            BinOp::Eq | BinOp::Ne | BinOp::Lt | BinOp::Le | BinOp::Gt | BinOp::Ge | BinOp::Is | BinOp::IsNot
        )
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum LikeOp {
    Like,
    Glob,
    Regexp,
    Match,
}

#[derive(Debug, Clone)]
pub enum Expr {
    Lit(Value),
    /// Column reference; `dq` marks a double-quoted bare name that may fall
    /// back to a string literal.
    Column { table: Option<String>, name: String, dq: bool },
    Unary(UnOp, Box<Expr>),
    Binary(BinOp, Box<Expr>, Box<Expr>),
    IsNull(Box<Expr>),
    NotNull(Box<Expr>),
    Between { expr: Box<Expr>, lo: Box<Expr>, hi: Box<Expr>, not: bool },
    InList { expr: Box<Expr>, list: Vec<Expr>, not: bool },
    Like { op: LikeOp, expr: Box<Expr>, pattern: Box<Expr>, escape: Option<Box<Expr>>, not: bool },
    Case { operand: Option<Box<Expr>>, whens: Vec<(Expr, Expr)>, else_: Option<Box<Expr>> },
    Cast(Box<Expr>, String),
    Collate(Box<Expr>, String),
    Func { name: String, args: Vec<Expr>, distinct: bool, star: bool },
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum ConflictAction {
    Rollback,
    Abort,
    Fail,
    Ignore,
    Replace,
}

/// A CHECK constraint with the text used in its error message (the
/// constraint name, or the expression's source text).
#[derive(Debug, Clone)]
pub struct CheckDef {
    pub expr: Expr,
    pub name: String,
}

#[derive(Debug, Clone)]
pub struct ColumnDef {
    pub name: String,
    pub type_name: String,
    pub primary_key: bool,
    pub pk_desc: bool,
    pub pk_conflict: Option<ConflictAction>,
    pub autoincrement: bool,
    pub not_null: bool,
    pub not_null_conflict: Option<ConflictAction>,
    pub unique: bool,
    pub unique_conflict: Option<ConflictAction>,
    pub checks: Vec<CheckDef>,
    pub default: Option<Expr>,
    pub collate: Option<String>,
}

#[derive(Debug, Clone)]
pub enum TableConstraint {
    PrimaryKey(Vec<IndexedColumn>, Option<ConflictAction>, bool),
    Unique(Vec<IndexedColumn>, Option<ConflictAction>),
    Check(CheckDef),
    ForeignKey,
}

#[derive(Debug, Clone)]
pub struct IndexedColumn {
    pub expr: Expr,
    pub collate: Option<String>,
    #[allow(dead_code)]
    pub desc: bool,
}

#[derive(Debug, Clone)]
pub struct CreateTable {
    pub name: String,
    pub if_not_exists: bool,
    pub columns: Vec<ColumnDef>,
    pub constraints: Vec<TableConstraint>,
}

#[derive(Debug, Clone)]
pub enum InsertSource {
    Values(Vec<Vec<Expr>>),
    Select(Box<Select>),
    Default,
}

#[derive(Debug, Clone)]
pub enum UpsertAction {
    Nothing,
    Update { sets: Vec<(String, Expr)>, where_: Option<Expr> },
