CREATE INDEX b_name ON b(name);
CREATE UNIQUE INDEX a_x ON a(x);
SELECT type, name, tbl_name FROM sqlite_schema WHERE type = 'index' ORDER BY name;
-- Automatic indexes cannot be dropped directly.
