/// Words that can never be used as bare identifiers or implicit aliases.
const RESERVED: &[&str] = &[
    "ALL", "ALTER", "AND", "AS", "BETWEEN", "BY", "CASE", "CHECK", "COLLATE", "CONSTRAINT", "CREATE",
    "CROSS", "DEFAULT", "DELETE", "DISTINCT", "DROP", "ELSE", "ESCAPE", "EXCEPT", "EXISTS", "FOREIGN",
    "FROM", "FULL", "GLOB", "GROUP", "HAVING", "IN", "INDEX", "INNER", "INSERT", "INTERSECT", "INTO",
    "IS", "ISNULL", "JOIN", "LEFT", "LIKE", "LIMIT", "MATCH", "NATURAL", "NOT", "NOTNULL", "NULL",
    "OFFSET", "ON", "OR", "ORDER", "OUTER", "PRIMARY", "REFERENCES", "REGEXP", "RETURNING", "RIGHT",
    "SELECT", "SET", "TABLE", "THEN", "TO", "UNION", "UNIQUE", "UPDATE", "USING", "VALUES", "WHEN",
    "WHERE", "WINDOW",
];

fn is_reserved(w: &str) -> bool {
    RESERVED.iter().any(|k| k.eq_ignore_ascii_case(w))
}

pub struct Parser {
    toks: Vec<Token>,
    pos: usize,
    src: String,
}

type PResult<T> = Result<T, String>;

pub fn parse_statement(sql: &str) -> PResult<Stmt> {
    let toks = tokenize(sql)?;
    let mut p = Parser { toks, pos: 0, src: sql.to_string() };
    let stmt = p.parse_stmt()?;
    p.eat_op(";");
    if !matches!(p.peek(), Tok::Eof) {
        return Err(p.err());
    }
    Ok(stmt)
}

