pub fn walk_expr(e: &Expr, f: &mut dyn FnMut(&Expr)) {
    f(e);
    match e {
        Expr::Lit(_) | Expr::Column { .. } | Expr::Subquery(_) | Expr::Exists(_) => {}
        Expr::Unary(_, x) | Expr::IsNull(x) | Expr::NotNull(x) | Expr::Cast(x, _) | Expr::Collate(x, _) => {
            walk_expr(x, f)
        }
        Expr::InSelect { expr, .. } => walk_expr(expr, f),
        Expr::Binary(_, l, r) => {
            walk_expr(l, f);
            walk_expr(r, f);
        }
        Expr::Between { expr, lo, hi, .. } => {
            walk_expr(expr, f);
            walk_expr(lo, f);
            walk_expr(hi, f);
        }
        Expr::InList { expr, list, .. } => {
            walk_expr(expr, f);
            list.iter().for_each(|x| walk_expr(x, f));
        }
        Expr::Like { expr, pattern, escape, .. } => {
            walk_expr(expr, f);
            walk_expr(pattern, f);
            if let Some(x) = escape {
                walk_expr(x, f);
            }
        }
        Expr::Case { operand, whens, else_ } => {
            if let Some(x) = operand {
                walk_expr(x, f);
            }
            for (w, t) in whens {
                walk_expr(w, f);
                walk_expr(t, f);
            }
            if let Some(x) = else_ {
                walk_expr(x, f);
            }
        }
        Expr::Func { args, filter, order_by, .. } => {
            args.iter().for_each(|x| walk_expr(x, f));
            if let Some(x) = filter {
                walk_expr(x, f);
            }
            order_by.iter().for_each(|t| walk_expr(&t.expr, f));
        }
    }
}

