                }
            }
            None => v = 16,
        }
    }
    (v / 4 + 1).min(255)
}

/// SQLite's LogEst: roughly 10*log2(x).
pub fn log_est(mut x: u64) -> i32 {
    const A: [i32; 8] = [0, 2, 3, 5, 6, 7, 8, 9];
    let mut y: i32 = 40;
    if x < 8 {
        if x < 2 {
            return 0;
        }
        while x < 8 {
            y -= 10;
            x <<= 1;
        }
    } else {
        let i = 60 - x.leading_zeros() as i32;
        y += i * 10;
        x >>= i;
    }
    A[(x & 7) as usize] + y - 10
}

