    pub fn from_call(name: &str, nargs: usize, star: bool) -> Option<AggKind> {
        Some(match name {
            "count" if star || nargs == 0 => AggKind::CountStar,
            "count" => AggKind::Count,
            "sum" => AggKind::Sum,
            "total" => AggKind::Total,
            "avg" => AggKind::Avg,
            "min" if nargs <= 1 => AggKind::Min,
            "max" if nargs <= 1 => AggKind::Max,
            "group_concat" | "string_agg" => AggKind::GroupConcat,
            _ => return None,
        })
    }

