    pub fn arg_range(self, name: &str) -> (usize, usize) {
        match self {
            AggKind::CountStar => (0, 0),
            AggKind::GroupConcat if name == "string_agg" => (2, 2),
            AggKind::GroupConcat => (1, 2),
            _ => (1, 1),
        }
    }

    fn is_minmax(self) -> bool {
        matches!(self, AggKind::Min | AggKind::Max)
    }
