/// Compare two sort-key values under one ORDER BY term.
pub fn order_cmp(x: &Value, y: &Value, desc: bool, nulls_first: Option<bool>, coll: Coll) -> Ordering {
    match (x.is_null(), y.is_null(), nulls_first) {
        (true, false, Some(nf)) => {
            if nf {
                Ordering::Less
            } else {
                Ordering::Greater
            }
        }
        (false, true, Some(nf)) => {
            if nf {
                Ordering::Greater
            } else {
                Ordering::Less
            }
        }
        _ => {
            let o = compare_values_coll(x, y, coll);
            if desc {
                o.reverse()
            } else {
                o
            }
        }
    }
}

#[derive(Debug, Default)]
struct SumCtx {
    cnt: i64,
    isum: i64,
    rsum: f64,
    rerr: f64,
    approx: bool,
    ovrfl: bool,
}

const BIG: i64 = 4503599627370496;

impl SumCtx {
    /// Kahan-Babuska-Neumaier summation step.
    fn kbn(&mut self, r: f64) {
        let s = self.rsum;
        let t = s + r;
        if s.abs() > r.abs() {
            self.rerr += (s - t) + r;
        } else {
            self.rerr += (r - t) + s;
        }
        self.rsum = t;
    }

    fn kbn_int(&mut self, v: i64) {
        if v <= -BIG || v >= BIG {
            let sm = v % 16384;
            self.kbn((v - sm) as f64);
            self.kbn(sm as f64);
        } else {
            self.kbn(v as f64);
        }
    }

    fn init(&mut self, v: i64) {
        if v <= -BIG || v >= BIG {
            let sm = v % 16384;
            self.rsum = (v - sm) as f64;
            self.rerr = sm as f64;
        } else {
            self.rsum = v as f64;
            self.rerr = 0.0;
        }
    }

    fn step(&mut self, v: &Value) {
        let nv = match v {
            Value::Null => return,
            Value::Integer(i) => Value::Integer(*i),
            Value::Real(r) => Value::Real(*r),
            Value::Text(s) => text_numeric_affinity(s, false).unwrap_or(Value::Real(v.to_f64())),
            Value::Blob(_) => Value::Real(v.to_f64()),
        };
        self.cnt += 1;
        match nv {
            Value::Integer(i) => {
                if !self.approx {
                    match self.isum.checked_add(i) {
                        Some(x) => self.isum = x,
                        None => {
                            self.ovrfl = true;
                            self.init(self.isum);
                            self.approx = true;
                            self.kbn_int(i);
                        }
                    }
                } else {
                    self.kbn_int(i);
                }
            }
            Value::Real(r) => {
                if !self.approx {
                    self.init(self.isum);
                    self.approx = true;
                } else {
                    self.ovrfl = false;
                }
                self.kbn(r);
            }
            _ => unreachable!(),
        }
    }

    fn real_value(&self) -> f64 {
        if self.approx {
            if self.rerr.is_finite() {
                self.rsum + self.rerr
            } else {
                self.rsum
            }
        } else {
            self.isum as f64
        }
    }
}

