/// A read varint and its length in bytes.
pub fn read_varint(b: &[u8]) -> (u64, usize) {
    let mut v: u64 = 0;
    for i in 0..9 {
        let Some(&x) = b.get(i) else {
            return (v, i.max(1));
        };
        if i == 8 {
            return ((v << 8) | x as u64, 9);
        }
        v = (v << 7) | (x & 0x7f) as u64;
        if x & 0x80 == 0 {
            return (v, i + 1);
        }
    }
    (v, 9)
}

fn be(b: &[u8]) -> u64 {
    b.iter().fold(0u64, |acc, &x| (acc << 8) | x as u64)
}

