        let mut schema: Vec<(i64, Vec<u8>)> = Vec::new();
        for r in self.schema_rows() {
            let (Value::Text(kind), Value::Text(name), Value::Text(tbl)) = (&r[0], &r[1], &r[2])
            else {
                continue;
            };
            let root = match kind.as_str() {
