use std::cmp::Ordering;
use std::collections::BTreeMap;

use crate::ast::*;
use crate::db::{key, Column, Database, Table};
use crate::eval::{bind, eval, BExpr, Scope, Source};
use crate::value::{apply_affinity, compare, Affinity, Value};

pub type Rows = Vec<Vec<Value>>;

/// Executes one statement; returns the result rows (possibly empty).
pub fn execute(db: &mut Database, stmt: &Stmt) -> Result<Rows, String> {
    match stmt {
        Stmt::CreateTable(ct) => create_table(db, ct).map(|_| Vec::new()),
        Stmt::DropTable { name, if_exists } => {
            if db.tables.remove(&key(name)).is_none() && !*if_exists {
                return Err(format!("no such table: {}", name));
            }
            Ok(Vec::new())
        }
        Stmt::Insert(ins) => insert(db, ins).map(|_| Vec::new()),
        Stmt::Select(sel) => select(db, sel),
    }
}

fn create_table(db: &mut Database, ct: &CreateTable) -> Result<(), String> {
    if db.tables.contains_key(&key(&ct.name)) {
        if ct.if_not_exists {
            return Ok(());
        }
        return Err(format!("table {} already exists", ct.name));
    }
    let mut columns: Vec<Column> = Vec::new();
    for cd in &ct.columns {
        if columns.iter().any(|c| c.name.eq_ignore_ascii_case(&cd.name)) {
            return Err(format!("duplicate column name: {}", cd.name));
        }
        let mut default = None;
        for c in &cd.constraints {
            if let ColumnConstraint::Default(e) = c {
                default = Some(e.clone());
            }
        }
        columns.push(Column {
            name: cd.name.clone(),
            decl_type: cd.type_name.clone(),
            affinity: Affinity::from_type(cd.type_name.as_deref()),
            default,
        });
    }
    db.tables.insert(
        key(&ct.name),
        Table { name: ct.name.clone(), columns, rows: BTreeMap::new(), sql: ct.sql.clone() },
    );
    Ok(())
}

fn insert(db: &mut Database, ins: &Insert) -> Result<(), String> {
    let table = db.table(&ins.table)?;
    let ncols = table.columns.len();
    // map each supplied value position to a table column
    let targets: Vec<usize> = match &ins.columns {
        None => (0..ncols).collect(),
        Some(names) => {
            let mut v = Vec::new();
            for n in names {
                match table.column_index(n) {
                    Some(i) => v.push(i),
                    None => return Err(format!("table {} has no column named {}", table.name, n)),
                }
            }
            v
        }
    };
    let empty = Scope::empty();
    let mut new_rows = Vec::with_capacity(ins.rows.len());
    for row in &ins.rows {
        if row.len() != targets.len() {
            return Err(match &ins.columns {
                None => format!(
                    "table {} has {} columns but {} values were supplied",
                    table.name,
                    ncols,
                    row.len()
                ),
                Some(_) => format!("{} values for {} columns", row.len(), targets.len()),
            });
        }
        let mut vals: Vec<Option<Value>> = vec![None; ncols];
        for (e, &ti) in row.iter().zip(&targets) {
            let b = bind(e, &empty)?;
            vals[ti] = Some(eval(&b, &[])?);
        }
        let mut full = Vec::with_capacity(ncols);
        for (i, v) in vals.into_iter().enumerate() {
