fn fp_decode(r: f64, mut iround: i32, mxround: i32) -> FpDecode {
    if r.is_nan() {
        return FpDecode { neg: false, z: vec![], idp: 0, special: 2 };
    }
    let neg = r < 0.0;
    let r = r.abs();
    if r.is_infinite() {
