    let (mant, exp) = s.split_once('e').unwrap();
    let exp: i32 = exp.parse().unwrap();
    let mut z: Vec<u8> = mant.bytes().filter(|c| c.is_ascii_digit()).collect();
    let mut idp = exp + 1;
