use std::panic::{catch_unwind, AssertUnwindSafe};

fn run_statement(db: &mut db::Database, sql: &str) -> Result<String, String> {
    let stmt = parser::parse_statement(sql)?;
    let rows = exec::execute(db, &stmt)?;
    let mut out = String::new();
    for row in rows {
        for (i, v) in row.iter().enumerate() {
            if i > 0 {
                out.push('|');
            }
            out.push_str(&v.to_output());
        }
        out.push('\n');
    }
    Ok(out)
}

fn main() {
    let input = io::read_stdin();
    let mut db = db::Database::new();
    for sql in split::split(&input) {
        let res = catch_unwind(AssertUnwindSafe(|| run_statement(&mut db, &sql)));
        match res {
            Ok(Ok(out)) => io::write_stdout(&out),
            Ok(Err(msg)) => io::write_stdout(&format!("Error: {}\n", msg.replace(['\n', '\r'], " "))),
            Err(_) => io::write_stdout("Error: internal error\n"),
        }
    }
    io::flush_stdout();
}
// In-memory database storage.

use std::collections::BTreeMap;

use crate::ast::Expr;
use crate::value::{Affinity, Coll, Value};

#[derive(Debug, Clone)]
pub struct Column {
    pub name: String,
    pub decl_type: Option<String>,
    pub affinity: Affinity,
    pub default: Option<Expr>,
    pub coll: Option<Coll>,
}

#[derive(Debug, Clone)]
pub struct Table {
    pub name: String,
    pub columns: Vec<Column>,
    /// Rows keyed by rowid.
    pub rows: BTreeMap<i64, Vec<Value>>,
    pub sql: String,
}

impl Table {
    pub fn column_index(&self, name: &str) -> Option<usize> {
        self.columns.iter().position(|c| c.name.eq_ignore_ascii_case(name))
    }

    pub fn next_rowid(&self) -> i64 {
        match self.rows.keys().next_back() {
            Some(&k) if k < i64::MAX => k + 1,
            Some(_) => i64::MAX, // TODO: random search for a free rowid (M3)
            None => 1,
        }
    }
}

#[derive(Debug, Default)]
pub struct Database {
    /// Tables keyed by ASCII-lowercased name.
    pub tables: BTreeMap<String, Table>,
}

pub fn key(name: &str) -> String {
    name.to_ascii_lowercase()
}

impl Database {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn table(&self, name: &str) -> Result<&Table, String> {
        self.tables.get(&key(name)).ok_or_else(|| format!("no such table: {}", name))
    }

    pub fn table_mut(&mut self, name: &str) -> Result<&mut Table, String> {
        self.tables.get_mut(&key(name)).ok_or_else(|| format!("no such table: {}", name))
    }
}
