fn make_cmp(op: BinOp, l: BExpr, r: BExpr) -> Result<BExpr, String> {
    let aff = comparison_affinity(affinity(&l), affinity(&r));
    let coll = check_coll(binary_coll(&l, &r))?;
    Ok(BExpr::Cmp(op, bx(l), bx(r), aff, coll))
}

