/// Numeric affinity applied to a text value (applyNumericAffinity).
fn numeric_from_text(s: &str, try_int: bool) -> Option<Value> {
    let (r, rc) = atof(s.as_bytes());
    if rc <= 0 {
        return None;
    }
    if rc == 1 {
        let (i, irc) = atoi64(s.as_bytes());
        if irc == 0 {
            return Some(Value::Integer(i));
        }
