use crate::value::{compare, Affinity, Coll, Value};

#[derive(Debug, Clone)]
pub struct Column {
    pub name: String,
    pub decl_type: Option<String>,
    pub affinity: Affinity,
    pub default: Option<Expr>,
    pub coll: Option<Coll>,
    /// `Some(clause)` if the column is NOT NULL (clause None = default ABORT).
    pub not_null: Option<Option<Conflict>>,
}

#[derive(Debug, Clone)]
pub struct Check {
    /// Constraint name, or the expression text.
    pub name: String,
    pub expr: Expr,
}

/// A value used as an index key: text is normalized for the index collation
/// so that plain comparison matches the collation.
#[derive(Debug, Clone)]
pub struct KeyVal(pub Value);

impl PartialEq for KeyVal {
    fn eq(&self, o: &Self) -> bool {
        self.cmp(o) == Ordering::Equal
    }
}
impl Eq for KeyVal {}
impl PartialOrd for KeyVal {
    fn partial_cmp(&self, o: &Self) -> Option<Ordering> {
        Some(self.cmp(o))
    }
}
impl Ord for KeyVal {
    fn cmp(&self, o: &Self) -> Ordering {
        compare(&self.0, &o.0)
    }
}

pub fn key_val(v: &Value, coll: Coll) -> KeyVal {
    match (v, coll) {
        (Value::Text(s), Coll::NoCase) => KeyVal(Value::Text(s.to_ascii_lowercase())),
        (Value::Text(s), Coll::Rtrim) => KeyVal(Value::Text(s.trim_end_matches(' ').to_string())),
        _ => KeyVal(v.clone()),
    }
}

#[derive(Debug, Clone)]
pub struct Index {
    pub name: String,
    pub cols: Vec<usize>,
    pub colls: Vec<Coll>,
    pub unique: bool,
    pub conflict: Option<Conflict>,
    pub entries: BTreeSet<(Vec<KeyVal>, i64)>,
}

impl Index {
    pub fn key(&self, row: &[Value]) -> Vec<KeyVal> {
        self.cols.iter().zip(&self.colls).map(|(&c, &coll)| key_val(&row[c], coll)).collect()
    }

    /// A row other than `except` whose key equals the key of `row`
    /// (never for keys containing NULL).
    pub fn find_conflict(&self, row: &[Value], except: Option<i64>) -> Option<i64> {
        let k = self.key(row);
        if k.iter().any(|v| v.0.is_null()) {
            return None;
        }
        let lo = (k.clone(), i64::MIN);
        let hi = (k, i64::MAX);
        self.entries.range(lo..=hi).map(|(_, r)| *r).find(|r| Some(*r) != except)
    }
}

