/// A value used as an index key: text is normalized for the index collation
/// so that plain comparison matches the collation.
#[derive(Debug, Clone)]
pub struct KeyVal(pub Value);

impl PartialEq for KeyVal {
    fn eq(&self, o: &Self) -> bool {
        self.cmp(o) == Ordering::Equal
    }
}
impl Eq for KeyVal {}
impl PartialOrd for KeyVal {
    fn partial_cmp(&self, o: &Self) -> Option<Ordering> {
        Some(self.cmp(o))
    }
}
impl Ord for KeyVal {
    fn cmp(&self, o: &Self) -> Ordering {
        compare(&self.0, &o.0)
    }
}

pub fn key_val(v: &Value, coll: Coll) -> KeyVal {
    match (v, coll) {
        (Value::Text(s), Coll::NoCase) => KeyVal(Value::Text(s.to_ascii_lowercase())),
        (Value::Text(s), Coll::Rtrim) => KeyVal(Value::Text(s.trim_end_matches(' ').to_string())),
        _ => KeyVal(v.clone()),
    }
}

#[derive(Debug, Clone)]
pub struct Index {
    #[allow(dead_code)] // used by schema output in later milestones
    pub name: String,
    pub cols: Vec<usize>,
    pub colls: Vec<Coll>,
    pub unique: bool,
    pub conflict: Option<Conflict>,
    pub entries: BTreeSet<(Vec<KeyVal>, i64)>,
}

impl Index {
    pub fn key(&self, row: &[Value]) -> Vec<KeyVal> {
        self.cols.iter().zip(&self.colls).map(|(&c, &coll)| key_val(&row[c], coll)).collect()
    }

    /// A row other than `except` whose key equals the key of `row`
    /// (never for keys containing NULL).
    pub fn find_conflict(&self, row: &[Value], except: Option<i64>) -> Option<i64> {
        let k = self.key(row);
        if k.iter().any(|v| v.0.is_null()) {
            return None;
        }
        let lo = (k.clone(), i64::MIN);
        let hi = (k, i64::MAX);
        self.entries.range(lo..=hi).map(|(_, r)| *r).find(|r| Some(*r) != except)
    }
}

#[derive(Debug, Clone)]
pub struct Table {
    pub name: String,
    pub columns: Vec<Column>,
    /// Rows keyed by rowid.
    pub rows: BTreeMap<i64, Vec<Value>>,
    #[allow(dead_code)] // used by schema output in later milestones
    pub sql: String,
    /// Column that aliases the rowid (INTEGER PRIMARY KEY).
    pub ipk: Option<usize>,
    /// Conflict clause of the INTEGER PRIMARY KEY.
    pub pk_conflict: Option<Conflict>,
    pub autoinc: bool,
    /// Largest rowid ever used (AUTOINCREMENT).
    pub seq: i64,
    pub checks: Vec<Check>,
    pub indexes: Vec<Index>,
}

impl Table {
    pub fn column_index(&self, name: &str) -> Option<usize> {
        self.columns.iter().position(|c| c.name.eq_ignore_ascii_case(name))
    }

    /// Chooses a rowid for a new row.
    pub fn next_rowid(&self) -> Result<i64, String> {
        let max = self.rows.keys().next_back().copied().unwrap_or(0);
        if self.autoinc {
            let top = max.max(self.seq);
            return if top == i64::MAX { Err("database or disk is full".to_string()) } else { Ok(top + 1) };
        }
        if max < i64::MAX {
            return Ok(max.max(0) + 1);
        }
        // all large rowids used: search for a free one
        let mut x: u64 = 0x9E37_79B9_7F4A_7C15 ^ self.rows.len() as u64;
        for _ in 0..1000 {
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            let cand = (x >> 1) as i64;
            if cand > 0 && !self.rows.contains_key(&cand) {
                return Ok(cand);
            }
        }
        Err("database or disk is full".to_string())
    }

    fn add_row(&mut self, rowid: i64, row: Vec<Value>) {
        for idx in &mut self.indexes {
            let k = idx.key(&row);
            idx.entries.insert((k, rowid));
        }
        self.rows.insert(rowid, row);
    }

    fn remove_row(&mut self, rowid: i64) -> Option<Vec<Value>> {
        let row = self.rows.remove(&rowid)?;
        for idx in &mut self.indexes {
            let k = idx.key(&row);
            idx.entries.remove(&(k, rowid));
        }
        Some(row)
    }
}

