/// Executes one statement; returns the result rows (possibly empty).
pub fn execute(db: &mut Database, stmt: &Stmt) -> Result<Rows, String> {
    match stmt {
        Stmt::CreateTable(ct) => create_table(db, ct).map(|_| Vec::new()),
        Stmt::DropTable { name, if_exists } => {
            if db.tables.remove(&key(name)).is_none() && !*if_exists {
                return Err(format!("no such table: {}", name));
            }
            Ok(Vec::new())
        }
        Stmt::Insert(ins) => run_dml(db, |db, ctx| insert(db, ins, ctx)),
        Stmt::Update(upd) => run_dml(db, |db, ctx| update(db, upd, ctx)),
        Stmt::Delete(del) => run_dml(db, |db, ctx| delete(db, del, ctx)),
        Stmt::Select(sel) => query::select(db, sel),
    }
}

