fn run_dml<F>(db: &mut Database, f: F) -> Result<Rows, String>
where
    F: FnOnce(&mut Database, &mut Ctx) -> Result<Rows, String>,
{
    let mark = db.mark();
    let mut ctx = Ctx::default();
    match f(db, &mut ctx) {
        Ok(rows) => {
            db::set_changes(ctx.changes);
            db.commit();
            Ok(rows)
        }
        Err(e) => {
            if ctx.keep {
                db::set_changes(ctx.changes);
                db.commit();
            } else {
                db.rollback_to(mark);
                if ctx.started {
                    db::set_changes(0);
                }
            }
            Err(e)
        }
    }
}
