// ---------- expression analysis ----------

/// One past the largest row position an expression reads at this query
/// level (0 = none); usize::MAX if it has a correlated subquery.
pub fn refs(e: &BExpr) -> usize {
    match e {
        BExpr::Col { idx, .. } => idx + 1,
        BExpr::Sub(sq) if sq.correlated => usize::MAX,
        _ => children(e).into_iter().map(refs).max().unwrap_or(0),
    }
}

/// Splits an AND tree into its terms.
pub fn conjuncts(e: BExpr, out: &mut Vec<BExpr>) {
    match e {
        BExpr::And(l, r) => {
            conjuncts(*l, out);
            conjuncts(*r, out);
        }
        e => out.push(e),
    }
}

fn same(a: &BExpr, b: &BExpr) -> bool {
    format!("{:?}", a) == format!("{:?}", b)
}

fn flip(op: BinOp) -> BinOp {
    match op {
        BinOp::Lt => BinOp::Gt,
        BinOp::Le => BinOp::Ge,
        BinOp::Gt => BinOp::Lt,
        BinOp::Ge => BinOp::Le,
        o => o,
    }
}

fn skip_collate(e: &BExpr) -> &BExpr {
    match e {
        BExpr::Collate(x, _) => skip_collate(x),
        e => e,
    }
}

/// Whether a comparison with affinity `cmp` can use an index column with
/// affinity `col` (sqlite3IndexAffinityOk).
fn aff_ok(cmp: Affinity, col: Affinity) -> bool {
    match cmp {
        Affinity::None | Affinity::Blob => true,
        Affinity::Text => col == Affinity::Text,
        _ => col.is_numeric(),
    }
}

