fn select_refs(q: &Select, out: &mut Vec<(Option<String>, String)>) {
    fn item(it: &TableItem, out: &mut Vec<(Option<String>, String)>) {
        if let TableItem::Subquery { query, .. } = it {
            select_refs(query, out);
        }
    }
    let mut exprs: Vec<&Expr> = Vec::new();
    for core in &q.cores {
