}

pub type PResult<T> = Result<T, String>;

pub fn parse_statement(src: &str) -> PResult<Stmt> {
    let toks = tokenize(src)?;
    let mut p = Parser { src, toks, pos: 0, temp: false };
    let stmt = p.statement()?;
    if !p.at_eof() {
        return Err(p.err_near());
    }
    Ok(stmt)
}

