-- @timeout 5
-- Performance: walking a 100k-node tree (parent pointers, indexed) with a
-- recursive CTE, and UNION-based deduplication over 20k distinct values.
-- Each recursion step must use the index on parent (equality lookup), and
-- UNION's duplicate check must not be a linear scan of all previous rows.
CREATE TABLE node(id INTEGER PRIMARY KEY, parent INTEGER, w INTEGER);
WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x + 1 FROM c WHERE x < 100000)
INSERT INTO node SELECT x, CASE WHEN x = 1 THEN NULL ELSE x / 2 END, x % 10 FROM c;
CREATE INDEX node_parent ON node(parent);

-- All descendants of the root with their depth (a binary heap: depth = floor(log2(id))).
WITH RECURSIVE d(id, depth) AS (SELECT 1, 0 UNION ALL SELECT n.id, d.depth + 1 FROM node n JOIN d ON n.parent = d.id)
SELECT count(*), max(depth), sum(depth), sum(depth = 16) FROM d;

-- Subtree of node 3: size and weight.
WITH RECURSIVE d(id) AS (SELECT 3 UNION ALL SELECT n.id FROM node n JOIN d ON n.parent = d.id)
SELECT count(*), sum(node.w) FROM d JOIN node ON node.id = d.id;

-- Ancestors of many leaves: walk upward from 1000 start nodes.
WITH RECURSIVE up(start, id) AS (SELECT id, id FROM node WHERE id > 99000 UNION ALL
  SELECT up.start, n.parent FROM up JOIN node n ON n.id = up.id WHERE n.parent IS NOT NULL)
SELECT count(*), count(DISTINCT id) FROM up;

-- UNION dedup: x -> (x + 7) mod 20000 visits all 20000 values once, then stops.
WITH RECURSIVE c(x) AS (SELECT 0 UNION SELECT (x + 7) % 20000 FROM c)
SELECT count(*), sum(x), max(x) FROM c;

-- UNION dedup with two recursive arms producing many duplicates.
WITH RECURSIVE c(x) AS (SELECT 1 UNION SELECT (x * 2) % 30011 FROM c UNION SELECT (x * 3) % 30011 FROM c)
SELECT count(*), sum(x) FROM c;

-- Reachability in a graph with many cycles (UNION terminates).
CREATE TABLE edge(a INTEGER, b INTEGER);
WITH RECURSIVE c(x) AS (SELECT 0 UNION ALL SELECT x + 1 FROM c WHERE x < 29999)
INSERT INTO edge SELECT x, (x * 17 + 3) % 30000 FROM c UNION ALL SELECT x, (x + 1) % 30000 FROM c WHERE x % 2 = 0;
CREATE INDEX edge_a ON edge(a);
WITH RECURSIVE r(n) AS (SELECT 5 UNION SELECT e.b FROM edge e JOIN r ON e.a = r.n)
SELECT count(*), min(n), max(n) FROM r;
-- @timeout 5
-- Performance: window functions over a single 50k-row partition. Running
-- aggregates must be computed incrementally (recomputing each frame from
-- scratch is quadratic), and sliding / RANGE / GROUPS frames must find
-- their bounds without rescanning the partition for every row.
CREATE TABLE s(id INTEGER PRIMARY KEY, v INTEGER, k INTEGER);
WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x + 1 FROM c WHERE x < 50000)
INSERT INTO s SELECT x, (x * 7919) % 1009, x / 7 FROM c;

-- Running sum over the whole table (default frame).
SELECT count(*), sum(rs), max(rs) FROM (SELECT sum(v) OVER (ORDER BY id) AS rs FROM s);
-- Running count with peers (7 rows per k value).
SELECT sum(rc) FROM (SELECT count(*) OVER (ORDER BY k) AS rc FROM s);

-- Sliding sum and sliding max.
SELECT sum(ms) FROM (SELECT sum(v) OVER (ORDER BY id ROWS BETWEEN 10 PRECEDING AND 10 FOLLOWING) AS ms FROM s);
SELECT sum(mx) FROM (SELECT max(v) OVER (ORDER BY id ROWS 50 PRECEDING) AS mx FROM s);

-- Ranking over the whole table.
SELECT sum(rn), sum(nt) FROM (SELECT row_number() OVER (ORDER BY v, id) AS rn, ntile(100) OVER (ORDER BY v, id) AS nt FROM s);

-- RANGE and GROUPS frames.
SELECT sum(c) FROM (SELECT count(*) OVER (ORDER BY v RANGE BETWEEN 5 PRECEDING AND 5 FOLLOWING) AS c FROM s);
SELECT sum(g) FROM (SELECT sum(v) OVER (ORDER BY k GROUPS BETWEEN 2 PRECEDING AND 1 FOLLOWING) AS g FROM s);

-- lag with an offset and default.
SELECT count(*), sum(d) FROM (SELECT v - lag(v, 3, 0) OVER (ORDER BY id) AS d FROM s);
-- ORDER BY and LIMIT/OFFSET inside a recursive CTE.
-- * ORDER BY on the recursive part decides which queued row is processed
--   next (e.g. depth-first vs breadth-first).
-- * LIMIT on the recursive part caps the total number of rows the CTE ever
--   produces (anchor rows included); OFFSET skips output rows, but skipped
--   rows are still used to generate further rows.
-- The effect of the queue order is made visible through LIMIT: different
-- orders select different sets of rows.
CREATE TABLE org(id INTEGER PRIMARY KEY, name TEXT, boss INTEGER);
INSERT INTO org VALUES (1, 'ceo', NULL), (2, 'cto', 1), (3, 'cfo', 1), (4, 'dev1', 2),
  (5, 'dev2', 2), (6, 'acct', 3), (7, 'intern', 4);

-- Depth-first (deepest queued row first, ties by name DESC), first 4 rows.
WITH RECURSIVE t(id, name, depth) AS (
  SELECT id, name, 0 FROM org WHERE boss IS NULL
  UNION ALL
  SELECT org.id, org.name, t.depth + 1 FROM org JOIN t ON org.boss = t.id
  ORDER BY 3 DESC, 2 DESC LIMIT 4)
SELECT name, depth FROM t ORDER BY name;

-- Breadth-first (shallowest first, ties by name DESC), first 4 rows.
WITH RECURSIVE t(id, name, depth) AS (
  SELECT id, name, 0 FROM org WHERE boss IS NULL
  UNION ALL
  SELECT org.id, org.name, t.depth + 1 FROM org JOIN t ON org.boss = t.id
  ORDER BY 3, 2 DESC LIMIT 4)
SELECT name, depth FROM t ORDER BY name;

-- Without LIMIT, both orders produce the whole tree.
WITH RECURSIVE t(id, name, depth) AS (
  SELECT id, name, 0 FROM org WHERE boss IS NULL
  UNION ALL
  SELECT org.id, org.name, t.depth + 1 FROM org JOIN t ON org.boss = t.id
  ORDER BY 3 DESC, 2)
