# ---------------------------------------------------------------------------
# Statement splitting (SPEC.md §2.2)
# ---------------------------------------------------------------------------


def split_statements(script: str) -> list[str]:
    """Split a script on ';' outside quotes and comments.

    Comments are kept inside the statement text. Statements that contain
    only whitespace and comments are dropped.
    """
    out: list[str] = []
    buf: list[str] = []
    i, n = 0, len(script)
    while i < n:
        c = script[i]
        if c in "'\"`":
            j = i + 1
            while j < n:
                if script[j] == c:
                    if j + 1 < n and script[j + 1] == c:
                        j += 2
                        continue
                    break
                j += 1
            buf.append(script[i : j + 1])
            i = j + 1
        elif c == "[":
            j = script.find("]", i + 1)
            j = n - 1 if j < 0 else j
            buf.append(script[i : j + 1])
            i = j + 1
        elif script.startswith("--", i):
            j = script.find("\n", i)
            j = n if j < 0 else j
            buf.append(script[i:j])
            i = j
        elif script.startswith("/*", i):
            j = script.find("*/", i + 2)
            j = n if j < 0 else j + 2
            buf.append(script[i:j])
            i = j
        elif c == ";":
            out.append("".join(buf))
            buf = []
            i += 1
        else:
            buf.append(c)
            i += 1
    out.append("".join(buf))
    return [s.strip() for s in out if not _is_blank(s)]


def _is_blank(stmt: str) -> bool:
    s = re.sub(r"--[^\n]*", "", stmt)
    s = re.sub(r"/\*.*?(\*/|$)", "", s, flags=re.S)
    return s.strip() == ""


