        let start = (n as usize).checked_sub(1).map(|p| p * self.page_size);
        match start {
            Some(s) if n > 0 && s + self.page_size <= self.data.len() => Ok(&self.data[s..s + self.page_size]),
            _ => Err("database disk image is malformed".to_string()),
        }
    }

